    'kn': 'ಅಧಿಕೃತ ಪೋರ್ಟಲ್ ಮತ್ತು ಅಧಿಕೃತ ವ್ಯಕ್ತಿಯ ವಿವರಗಳನ್ನು ಬಳಸಿ. ನಿಮ್ಮ OTP ಅನ್ನು ಏಜೆಂಟ್‌ನೊಂದಿಗೆ ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ.',
