    'ta': 'வகை விவரக்குறிப்புகள், துல்லியமான புகைப்படங்கள், விநியோக பகுதி மற்றும் வரி-உள்ளடக்கிய சலுகை தேவைகளுடன் பொருத்துங்கள்.',
