  'Check current seller assessment, deposit and bid-security requirements on the portal. Do not assume a fixed caution-money fee.': {
    'mr': 'पोर्टलवर सध्याचे विक्रेता मूल्यांकन, ठेव आणि बिड-सिक्युरिटी आवश्यकता तपासा. निश्चित कॉशन-मनी फी आहे असे समजू नका.',
    'bn': 'পোর্টালে বর্তমান বিক্রেতা মূল্যায়ন, জমা ও বিড-সিকিউরিটি প্রয়োজনীয়তা যাচাই করুন। নির্দিষ্ট কশন-মানি ফি ধরে নেবেন না।',
    'pa': 'ਪੋਰਟਲ ਉੱਤੇ ਮੌਜੂਦਾ ਵਿਕਰੇਤਾ ਮੁਲਾਂਕਣ, ਜਮ੍ਹਾਂ ਰਾਸ਼ੀ ਅਤੇ ਬਿੱਡ-ਸੁਰੱਖਿਆ ਲੋੜਾਂ ਜਾਂਚੋ। ਸਥਿਰ ਕਾਸ਼ਨ-ਮਨੀ ਫੀਸ ਨਾ ਸਮਝੋ।',
    'gu': 'પોર્ટલ પર વર્તમાન વિક્રેતા મૂલ્યાંકન, ડિપોઝિટ અને બિડ-સિક્યુરિટી જરૂરિયાતો તપાસો. નિશ્ચિત કૉશન-મની ફી છે એમ ન માનો.',
    'ta': 'போர்ட்டலில் தற்போதைய விற்பனையாளர் மதிப்பீடு, வைப்புத்தொகை மற்றும் ஏல-பாதுகாப்பு தேவைகளை சரிபார்க்கவும். நிலையான காசன்-மணி கட்டணம் என்று கருதாதீர்கள்.',
    'te': 'పోర్టల్‌లో ప్రస్తుత విక్రేత మదింపు, డిపాజిట్ మరియు బిడ్-సెక్యూరిటీ అవసరాలను తనిఖీ చేయండి. స్థిర కాషన్-మనీ ఫీజు అని అనుకోకండి.',
    'kn': 'ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಪ್ರಸ್ತುತ ಮಾರಾಟಗಾರ ಮೌಲ್ಯಮಾಪನ, ಠೇವಣಿ ಮತ್ತು ಬಿಡ್-ಸೆಕ್ಯುರಿಟಿ ಅಗತ್ಯಗಳನ್ನು ಪರಿಶೀಲಿಸಿ. ಸ್ಥಿರ ಕಾಶನ್-ಮನಿ ಶುಲ್ಕ ಎಂದು ಭಾವಿಸಬೇಡಿ.',
  },
