  'Read buyer terms, delivery deadlines and payment conditions. Confirm you can fulfil before bidding.': {
    'mr': 'खरेदीदाराच्या अटी, डिलिव्हरी अंतिम तारखा आणि पेमेंट अटी वाचा. बिड करण्यापूर्वी पूर्ण करू शकता याची पुष्टी करा.',
    'bn': 'ক্রেতার শর্ত, ডেলিভারির শেষ সময়সীমা ও পেমেন্ট শর্ত পড়ুন। বিড করার আগে সরবরাহ করতে পারবেন কিনা নিশ্চিত করুন।',
    'pa': 'ਖਰੀਦਦਾਰ ਦੀਆਂ ਸ਼ਰਤਾਂ, ਡਿਲੀਵਰੀ ਦੀਆਂ ਆਖਰੀ ਤਰੀਕਾਂ ਅਤੇ ਭੁਗਤਾਨ ਸ਼ਰਤਾਂ ਪੜ੍ਹੋ। ਬਿੱਡ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਪੁਸ਼ਟੀ ਕਰੋ ਕਿ ਤੁਸੀਂ ਪੂਰਾ ਕਰ ਸਕਦੇ ਹੋ।',
    'gu': 'ખરીદદારની શરતો, ડિલિવરી ડેડલાઇન અને ચુકવણીની શરતો વાંચો. બિડ કરતા પહેલા પૂર્ણ કરી શકશો તેની પુષ્ટિ કરો.',
    'ta': 'வாங்குபவரின் விதிமுறைகள், விநியோக காலக்கெடு மற்றும் கட்டண நிலைமைகளைப் படியுங்கள். ஏலம் விடுவதற்கு முன் நிறைவேற்ற முடியும் என உறுதிசெய்யுங்கள்.',
    'te': 'కొనుగోలుదారు నిబంధనలు, డెలివరీ గడువులు మరియు చెల్లింపు షరతులను చదవండి. బిడ్ చేయడానికి ముందు నెరవేర్చగలరో నిర్ధారించుకోండి.',
    'kn': 'ಖರೀದಿದಾರರ ನಿಯಮಗಳು, ವಿತರಣಾ ಗಡುವುಗಳು ಮತ್ತು ಪಾವತಿ ಷರತ್ತುಗಳನ್ನು ಓದಿ. ಬಿಡ್ ಮಾಡುವ ಮೊದಲು ಪೂರೈಸಬಹುದೆಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  },
  'Fulfil your first order': {
    'mr': 'तुमची पहिली ऑर्डर पूर्ण करा',
    'bn': 'আপনার প্রথম অর্ডার সম্পন্ন করুন',
