  'Track acceptance, invoices and payment. A self-reported order stays unverified until the research team checks evidence.': {
    'mr': 'स्वीकृती, इनव्हॉइस आणि पेमेंट ट्रॅक करा. स्वयं-नोंदवलेली ऑर्डर संशोधन टीम पुरावा तपासेपर्यंत असत्यापित राहते.',
    'bn': 'গ্রহণ, চালান ও পেমেন্ট ট্র্যাক করুন। স্ব-প্রতিবেদিত অর্ডার গবেষণা দল প্রমাণ যাচাই না করা পর্যন্ত যাচাই-বিহীন থাকে।',
    'pa': 'ਸਵੀਕਾਰਤਾ, ਇਨਵਾਇਸ ਅਤੇ ਭੁਗਤਾਨ ਟਰੈਕ ਕਰੋ। ਖੋਜ ਟੀਮ ਸਬੂਤ ਦੀ ਜਾਂਚ ਕਰਨ ਤੱਕ ਖੁਦ-ਦਰਜ ਆਰਡਰ ਅਪੁਸ਼ਟ ਰਹਿੰਦਾ ਹੈ।',
    'gu': 'સ્વીકૃતિ, ઇનવોઇસ અને ચુકવણી ટ્રેક કરો. સંશોધન ટીમ પુરાવો ચકાસે ત્યાં સુધી સ્વ-રિપોર્ટેડ ઓર્ડર અચકાસાયેલ રહે છે.',
    'ta': 'ஏற்பு, விலைப்பட்டியல் மற்றும் கட்டணத்தைக் கண்காணிக்கவும். ஆராய்ச்சிக் குழு ஆதாரத்தைச் சரிபார்க்கும் வரை சுய-அறிக்கை ஆர்டர் சரிபார்க்கப்படாமல் இருக்கும்.',
    'te': 'అంగీకారం, ఇన్‌వాయిస్‌లు మరియు చెల్లింపును ట్రాక్ చేయండి. పరిశోధన బృందం ఆధారాలను తనిఖీ చేసేవరకు స్వీయ-నివేదిత ఆర్డర్ ధృవీకరించబడదు.',
    'kn': 'ಸ್ವೀಕಾರ, ಇನ್‌ವಾಯ್ಸ್‌ಗಳು ಮತ್ತು ಪಾವತಿಯನ್ನು ಟ್ರ್ಯಾಕ್ ಮಾಡಿ. ಸಂಶೋಧನಾ ತಂಡ ಪುರಾವೆಯನ್ನು ಪರಿಶೀಲಿಸುವವರೆಗೆ ಸ್ವಯಂ-ವರದಿ ಮಾಡಿದ ಆರ್ಡರ್ ಪರಿಶೀಲಿಸದೆ ಉಳಿಯುತ್ತದೆ.',
  },
  'Build your seller rating': {
    'mr': 'तुमचे विक्रेता रेटिंग तयार करा',
    'bn': 'আপনার বিক্রেতা রেটিং গড়ে তুলুন',
    'pa': 'ਆਪਣੀ ਵਿਕਰੇਤਾ ਰੇਟਿੰਗ ਬਣਾਓ',
    'gu': 'તમારું વિક્રેતા રેટિંગ બનાવો',
    'ta': 'உங்கள் விற்பனையாளர் மதிப்பீட்டை உருவாக்குங்கள்',
    'te': 'మీ విక్రేత రేటింగ్‌ను నిర్మించండి',
