  'Deliver consistently, resolve issues and review your seller dashboard. Orders and ratings are never guaranteed.': {
    'mr': 'सातत्याने पुरवठा करा, समस्या सोडवा आणि विक्रेता डॅशबोर्ड तपासा. ऑर्डर किंवा रेटिंगची कधीही खात्री नाही.',
    'bn': 'নিয়মিতভাবে সরবরাহ করুন, সমস্যা সমাধান করুন এবং বিক্রেতা ড্যাশবোর্ড পর্যালোচনা করুন। অর্ডার বা রেটিং কখনো নিশ্চিত নয়।',
    'pa': 'ਲਗਾਤਾਰ ਸਪਲਾਈ ਕਰੋ, ਮੁੱਦੇ ਹੱਲ ਕਰੋ ਅਤੇ ਆਪਣਾ ਵਿਕਰੇਤਾ ਡੈਸ਼ਬੋਰਡ ਦੇਖੋ। ਆਰਡਰ ਜਾਂ ਰੇਟਿੰਗ ਦੀ ਕਦੇ ਗਰੰਟੀ ਨਹੀਂ।',
    'gu': 'સતત ડિલિવરી કરો, સમસ્યાઓ ઉકેલો અને તમારું વિક્રેતા ડેશબોર્ડ તપાસો. ઓર્ડર અથવા રેટિંગની કદી ગેરંટી નથી.',
    'ta': 'தொடர்ந்து வழங்குங்கள், சிக்கல்களைத் தீர்க்கவும், உங்கள் விற்பனையாளர் டாஷ்போர்டைப் பரிசீலிக்கவும். ஆர்டர்கள் அல்லது மதிப்பீடுகள் ஒருபோதும் உத்தரவாதம் இல்லை.',
    'te': 'స్థిరంగా డెలివరీ చేయండి, సమస్యలను పరిష్కరించండి మరియు మీ విక్రేత డాష్‌బోర్డ్‌ను సమీక్షించండి. ఆర్డర్లు లేదా రేటింగ్‌లు ఎప్పుడూ హామీ ఇవ్వబడవు.',
    'kn': 'ಸ್ಥಿರವಾಗಿ ಪೂರೈಸಿ, ಸಮಸ್ಯೆಗಳನ್ನು ಪರಿಹರಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಮಾರಾಟಗಾರ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ. ಆರ್ಡರ್‌ಗಳು ಅಥವಾ ರೇಟಿಂಗ್‌ಗಳು ಎಂದಿಗೂ ಖಾತ್ರಿಪಡಿಸಲ್ಪಡುವುದಿಲ್ಲ.',
  },
