  'Understand GeM, check your readiness and work out the numbers — one clear step at a time.': {
    'mr': 'GeM समजून घ्या, तुमची तयारी तपासा आणि आकडे मोजा — एक-एक स्पष्ट पाऊल टाकत.',
    'bn': 'GeM বুঝুন, আপনার প্রস্তুতি যাচাই করুন এবং হিসাব করুন — এক এক স্পষ্ট পদক্ষেপে।',
    'pa': 'GeM ਸਮਝੋ, ਆਪਣੀ ਤਿਆਰੀ ਜਾਂਚੋ ਅਤੇ ਹਿਸਾਬ ਲਗਾਓ — ਇੱਕ-ਇੱਕ ਸਪਸ਼ਟ ਕਦਮ ਨਾਲ।',
    'gu': 'GeM સમજો, તમારી તૈયારી ચકાસો અને આંકડા ગણો — એક-એક સ્પષ્ટ પગલે.',
    'ta': 'GeM-ஐப் புரிந்துகொள்ளுங்கள், உங்கள் தயார்நிலையைச் சரிபார்த்து எண்களைக் கணக்கிடுங்கள் — ஒவ்வொரு தெளிவான படியாக.',
    'te': 'GeMని అర్థం చేసుకోండి, మీ సన్నద్ధతను తనిఖీ చేసి, సంఖ్యలను లెక్కించండి — ఒక్కో స్పష్టమైన అడుగుతో.',
    'kn': 'GeM ಅನ್ನು ಅರ್ಥಮಾಡಿಕೊಳ್ಳಿ, ನಿಮ್ಮ ಸನ್ನದ್ಧತೆಯನ್ನು ಪರಿಶೀಲಿಸಿ ಮತ್ತು ಸಂಖ್ಯೆಗಳನ್ನು ಲೆಕ್ಕಹಾಕಿ — ಒಂದೊಂದೇ ಸ್ಪಷ್ಟ ಹೆಜ್ಜೆಯಲ್ಲಿ.',
  },
