  'Public buyers purchase products and services through GeM.': {
    'mr': 'सार्वजनिक खरेदीदार GeM द्वारे उत्पादने आणि सेवा खरेदी करतात.',
    'bn': 'সরকারি ক্রেতারা GeM-এর মাধ্যমে পণ্য ও সেবা কেনেন।',
    'pa': 'ਸਰਕਾਰੀ ਖਰੀਦਦਾਰ GeM ਰਾਹੀਂ ਉਤਪਾਦ ਅਤੇ ਸੇਵਾਵਾਂ ਖਰੀਦਦੇ ਹਨ।',
    'gu': 'સરકારી ખરીદદારો GeM મારફતે ઉત્પાદનો અને સેવાઓ ખરીદે છે.',
    'ta': 'அரசு வாங்குபவர்கள் GeM மூலம் பொருட்கள் மற்றும் சேவைகளை வாங்குகின்றனர்.',
    'te': 'ప్రభుత్వ కొనుగోలుదారులు GeM ద్వారా ఉత్పత్తులు మరియు సేవలను కొనుగోలు చేస్తారు.',
    'kn': 'ಸರ್ಕಾರಿ ಖರೀದಿದಾರರು GeM ಮೂಲಕ ಉತ್ಪನ್ನಗಳು ಮತ್ತು ಸೇವೆಗಳನ್ನು ಖರೀದಿಸುತ್ತಾರೆ.',
  },
  'Built around your business': {
    'mr': 'तुमच्या व्यवसायाभोवती तयार केलेले',
    'bn': 'আপনার ব্যবসাকে ঘিরে তৈরি',
    'pa': 'ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਦੇ ਆਲੇ-ਦੁਆਲੇ ਬਣਾਇਆ',
    'gu': 'તમારા બિઝનેસની આસપાસ બનેલું',
    'ta': 'உங்கள் தொழிலைச் சுற்றி வடிவமைக்கப்பட்டது',
    'te': 'మీ వ్యాపారం చుట్టూ నిర్మించబడింది',
    'kn': 'ನಿಮ್ಮ ವ್ಯಾಪಾರದ ಸುತ್ತ ನಿರ್ಮಿಸಲಾಗಿದೆ',
  },
  'From office supplies to services, start with your category.': {
    'mr': 'कार्यालयीन साहित्यापासून सेवांपर्यंत, तुमच्या श्रेणीपासून सुरुवात करा.',
    'bn': 'অফিস সরবরাহ থেকে পরিষেবা পর্যন্ত, আপনার বিভাগ থেকে শুরু করুন।',
    'pa': 'ਦਫ਼ਤਰੀ ਸਮਾਨ ਤੋਂ ਸੇਵਾਵਾਂ ਤੱਕ, ਆਪਣੀ ਸ਼੍ਰੇਣੀ ਤੋਂ ਸ਼ੁਰੂ ਕਰੋ।',
    'gu': 'ઓફિસ સામગ્રીથી સેવાઓ સુધી, તમારી કેટેગરીથી શરૂ કરો.',
    'ta': 'அலுவலகப் பொருட்கள் முதல் சேவைகள் வரை, உங்கள் வகையிலிருந்து தொடங்குங்கள்.',
    'te': 'ఆఫీసు సామాగ్రి నుండి సేవల వరకు, మీ కేటగరీతో ప్రారంభించండి.',
    'kn': 'ಕಚೇರಿ ಸಾಮಗ್ರಿಗಳಿಂದ ಸೇವೆಗಳವರೆಗೆ, ನಿಮ್ಮ ವರ್ಗದಿಂದ ಪ್ರಾರಂಭಿಸಿ.',
  },
  'Your pace. Your information.': {
    'mr': 'तुमचा वेग. तुमची माहिती.',
    'bn': 'আপনার গতি। আপনার তথ্য।',
    'pa': 'ਤੁਹਾਡੀ ਰਫ਼ਤਾਰ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ।',
    'gu': 'તમારી ગતિ. તમારી માહિતી.',
    'ta': 'உங்கள் வேகம். உங்கள் தகவல்.',
    'te': 'మీ వేగం. మీ సమాచారం.',
    'kn': 'ನಿಮ್ಮ ವೇಗ. ನಿಮ್ಮ ಮಾಹಿತಿ.',
  },
  'Use the tools privately. Choose whether to save online.': {
    'mr': 'टूल्स खासगीरीत्या वापरा. ऑनलाइन सेव्ह करायचे की नाही ते तुम्ही ठरवा.',
    'bn': 'সরঞ্জামগুলি ব্যক্তিগতভাবে ব্যবহার করুন। অনলাইনে সংরক্ষণ করবেন কিনা তা বেছে নিন।',
    'pa': 'ਟੂਲ ਨਿੱਜੀ ਤੌਰ \'ਤੇ ਵਰਤੋ। ਆਨਲਾਈਨ ਸੇਵ ਕਰਨਾ ਹੈ ਜਾਂ ਨਹੀਂ, ਚੁਣੋ।',
    'gu': 'ટૂલ્સનો ખાનગી રીતે ઉપયોગ કરો. ઓનલાઇન સેવ કરવું કે નહીં તે પસંદ કરો.',
    'ta': 'கருவிகளை தனிப்பட்ட முறையில் பயன்படுத்துங்கள். ஆன்லைனில் சேமிக்க வேண்டுமா என்பதைத் தேர்வு செய்யுங்கள்.',
    'te': 'టూల్స్‌ను ప్రైవేట్‌గా ఉపయోగించండి. ఆన్‌లైన్‌లో సేవ్ చేయాలో లేదో ఎంచుకోండి.',
    'kn': 'ಪರಿಕರಗಳನ್ನು ಖಾಸಗಿಯಾಗಿ ಬಳಸಿ. ಆನ್‌ಲೈನ್‌ನಲ್ಲಿ ಉಳಿಸಬೇಕೆ ಎಂದು ಆಯ್ಕೆಮಾಡಿ.',
  },
  'A little help can make\nthe next step easier.': {
    'mr': 'थोडी मदत पुढचे पाऊल\\nसोपे करू शकते.',
    'bn': 'একটু সাহায্য পরবর্তী পদক্ষেপ\\nসহজ করতে পারে।',
    'pa': 'ਥੋੜ੍ਹੀ ਮਦਦ ਅਗਲਾ ਕਦਮ\\nਸੌਖਾ ਬਣਾ ਸਕਦੀ ਹੈ।',
    'gu': 'થોડી મદદ આગળનું પગલું\\nસરળ બનાવી શકે છે.',
    'ta': 'ஒரு சிறிய உதவி அடுத்த படியை\\nஎளிதாக்கும்.',
    'te': 'కొంచెం సహాయం తర్వాతి అడుగును\\nసులభతరం చేయగలదు.',
    'kn': 'ಸ್ವಲ್ಪ ಸಹಾಯ ಮುಂದಿನ ಹೆಜ್ಜೆಯನ್ನು\\nಸುಲಭಗೊಳಿಸಬಹುದು.',
  },
  'Ask about a workshop or request guidance from a CA partner.': {
    'mr': 'कार्यशाळेबद्दल विचारा किंवा CA पार्टनरकडून मार्गदर्शन मागा.',
    'bn': 'কর্মশালা সম্পর্কে জিজ্ঞাসা করুন বা CA পার্টনারের কাছ থেকে গাইডেন্স চান।',
    'pa': 'ਵਰਕਸ਼ਾਪ ਬਾਰੇ ਪੁੱਛੋ ਜਾਂ CA ਪਾਰਟਨਰ ਤੋਂ ਮਾਰਗਦਰਸ਼ਨ ਮੰਗੋ।',
    'gu': 'વર્કશોપ વિશે પૂછો અથવા CA પાર્ટનર પાસેથી માર્ગદર્શન માંગો.',
    'ta': 'பட்டறை பற்றி கேளுங்கள் அல்லது CA பார்ட்னரிடமிருந்து வழிகாட்டுதலைக் கேளுங்கள்.',
    'te': 'వర్క్‌షాప్ గురించి అడగండి లేదా CA పార్టనర్ నుండి మార్గదర్శకత్వం కోరండి.',
    'kn': 'ಕಾರ್ಯಾಗಾರದ ಬಗ್ಗೆ ಕೇಳಿ ಅಥವಾ CA ಪಾರ್ಟನರ್‌ನಿಂದ ಮಾರ್ಗದರ್ಶನ ಕೇಳಿ.',
  },
  'Find support →': {
    'mr': 'सहाय्य शोधा →',
    'bn': 'সহায়তা খুঁজুন →',
    'pa': 'ਸਹਾਇਤਾ ਲਓ →',
    'gu': 'સહાય શોધો →',
    'ta': 'உதவியைக் கண்டறியவும் →',
    'te': 'సహాయం పొందండి →',
    'kn': 'ಸಹಾಯ ಪಡೆಯಿರಿ →',
  },
  'Can I sell? Find your classification and what you need to get started.': {
    'mr': 'मी विकू शकतो का? तुमचे वर्गीकरण आणि सुरुवातीसाठी आवश्यक गोष्टी शोधा.',
    'bn': 'আমি কি বিক্রি করতে পারি? আপনার শ্রেণিবিভাগ ও শুরু করার প্রয়োজনীয়তা জানুন।',
    'pa': 'ਕੀ ਮੈਂ ਵੇਚ ਸਕਦਾ/ਸਕਦੀ ਹਾਂ? ਆਪਣਾ ਵਰਗੀਕਰਨ ਅਤੇ ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਲੋੜਾਂ ਲੱਭੋ।',
    'gu': 'હું વેચી શકું? તમારું વર્ગીકરણ અને શરૂ કરવા માટે જરૂરી બાબતો શોધો.',
    'ta': 'நான் விற்கலாமா? உங்கள் வகைப்பாடு மற்றும் தொடங்குவதற்குத் தேவையானவற்றைக் கண்டறியுங்கள்.',
    'te': 'నేను అమ్మవచ్చా? మీ వర్గీకరణ మరియు ప్రారంభించడానికి కావాల్సినవి కనుగొనండి.',
    'kn': 'ನಾನು ಮಾರಾಟ ಮಾಡಬಹುದೇ? ನಿಮ್ಮ ವರ್ಗೀಕರಣ ಮತ್ತು ಪ್ರಾರಂಭಿಸಲು ಬೇಕಾದವುಗಳನ್ನು ಕಂಡುಕೊಳ್ಳಿ.',
  },
  'What is possible? Explore a range using your own sales assumptions.': {
    'mr': 'काय शक्य आहे? तुमच्या स्वतःच्या विक्री गृहीतकांचा वापर करून श्रेणी एक्सप्लोर करा.',
    'bn': 'কী সম্ভব? আপনার নিজের বিক্রয় অনুমান ব্যবহার করে একটি পরিসর অন্বেষণ করুন।',
    'pa': 'ਕੀ ਸੰਭਵ ਹੈ? ਆਪਣੀਆਂ ਵਿਕਰੀ ਧਾਰਨਾਵਾਂ ਵਰਤਦੇ ਹੋਏ ਇੱਕ ਸੀਮਾ ਦੀ ਪੜਚੋਲ ਕਰੋ।',
    'gu': 'શું શક્ય છે? તમારી પોતાની વેચાણ ધારણાઓનો ઉપયોગ કરીને શ્રેણી શોધો.',
    'ta': 'என்ன சாத்தியம்? உங்கள் விற்பனை கருதுகோள்களைப் பயன்படுத்தி வரம்பை ஆராயுங்கள்.',
    'te': 'ఏమి సాధ్యం? మీ స్వంత విక్రయ అంచనాలను ఉపయోగించి పరిధిని అన్వేషించండి.',
    'kn': 'ಏನು ಸಾಧ್ಯ? ನಿಮ್ಮ ಸ್ವಂತ ಮಾರಾಟ ಊಹೆಗಳನ್ನು ಬಳಸಿ ಒಂದು ವ್ಯಾಪ್ತಿಯನ್ನು ಅನ್ವೇಷಿಸಿ.',
  },
  'What should I charge? Protect your margin before you quote.': {
    'mr': 'मी काय दर लावावा? कोट देण्यापूर्वी तुमचा मार्जिन सुरक्षित करा.',
    'bn': 'আমি কী দাম রাখব? উদ্ধৃতি দেওয়ার আগে আপনার মার্জিন সুরক্ষিত করুন।',
    'pa': 'ਮੈਨੂੰ ਕੀ ਲਾਉਣਾ ਚਾਹੀਦਾ ਹੈ? ਕੋਟ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣਾ ਮਾਰਜਿਨ ਬਚਾਓ।',
    'gu': 'મારે શું ચાર્જ કરવું જોઈએ? ક્વોટ આપતા પહેલા તમારું માર્જિન સુરક્ષિત કરો.',
    'ta': 'நான் என்ன கட்டணம் வசூலிக்க வேண்டும்? விலைப்புள்ளி கொடுப்பதற்கு முன் உங்கள் மார்ஜினைப் பாதுகாக்கவும்.',
    'te': 'నేను ఎంత చార్జ్ చేయాలి? కోట్ చేయడానికి ముందు మీ మార్జిన్‌ను రక్షించుకోండి.',
    'kn': 'ನಾನು ಎಷ್ಟು ಚಾರ್ಜ್ ಮಾಡಬೇಕು? ಕೋಟ್ ನೀಡುವ ಮೊದಲು ನಿಮ್ಮ ಮಾರ್ಜಿನ್ ಅನ್ನು ರಕ್ಷಿಸಿ.',
  },
  'Is it worth the effort? See costs, contribution and payback together.': {
    'mr': 'हा प्रयत्न फायदेशीर आहे का? खर्च, योगदान आणि परतफेड एकत्र पहा.',
    'bn': 'এটা কি চেষ্টা করার মতো? খরচ, অবদান ও ফেরত একসাথে দেখুন।',
    'pa': 'ਕੀ ਇਹ ਕੋਸ਼ਿਸ਼ ਕਰਨ ਯੋਗ ਹੈ? ਲਾਗਤਾਂ, ਯੋਗਦਾਨ ਅਤੇ ਵਾਪਸੀ ਇਕੱਠੇ ਦੇਖੋ।',
    'gu': 'શું આ પ્રયાસ યોગ્ય છે? ખર્ચ, ફાળો અને વળતર સાથે જુઓ.',
    'ta': 'இது முயற்சிக்கு தகுதியானதா? செலவுகள், பங்களிப்பு மற்றும் மீட்பு ஆகியவற்றை ஒன்றாகப் பாருங்கள்.',
    'te': 'ఇది ప్రయత్నానికి తగినదా? ఖర్చులు, సహకారం మరియు తిరిగి రావడం కలిపి చూడండి.',
    'kn': 'ಇದು ಪ್ರಯತ್ನಕ್ಕೆ ಯೋಗ್ಯವೇ? ವೆಚ್ಚಗಳು, ಕೊಡುಗೆ ಮತ್ತು ಮರುಪಾವತಿಯನ್ನು ಒಟ್ಟಿಗೆ ನೋಡಿ.',
  },
  'What do I do next? Turn your plan into a practical checklist.': {
    'mr': 'पुढे काय करावे? तुमची योजना व्यावहारिक चेकलिस्टमध्ये बदला.',
    'bn': 'এরপর কী করব? আপনার পরিকল্পনাকে বাস্তবসম্মত চেকলিস্টে পরিণত করুন।',
    'pa': 'ਅੱਗੇ ਕੀ ਕਰਨਾ ਹੈ? ਆਪਣੀ ਯੋਜਨਾ ਨੂੰ ਵਿਹਾਰਕ ਚੈੱਕਲਿਸਟ ਵਿੱਚ ਬਦਲੋ।',
    'gu': 'આગળ શું કરવું? તમારી યોજનાને વ્યવહારુ ચેકલિસ્ટમાં ફેરવો.',
