    'bn': 'আপনার ডকুমেন্ট উত্তরগুলি এগিয়ে নেওয়া হয়েছে। প্রতিটি কাজ সম্পন্ন হলে চিহ্নিত করুন, বা এটি প্রযোজ্য নয় নিশ্চিত করুন।',
    'pa': 'ਤੁਹਾਡੇ ਦਸਤਾਵੇਜ਼ ਜਵਾਬ ਅੱਗੇ ਲਿਆਏ ਗਏ ਹਨ। ਹਰ ਕੰਮ ਪੂਰਾ ਹੋਣ \'ਤੇ ਨਿਸ਼ਾਨ ਲਾਓ, ਜਾਂ ਪੁਸ਼ਟੀ ਕਰੋ ਕਿ ਇਹ ਲਾਗੂ ਨਹੀਂ ਹੈ।',
