    'ta': 'உங்கள் ஆவண பதில்கள் முன்னெடுக்கப்பட்டுள்ளன. ஒவ்வொரு பணியும் முடிந்தவுடன் குறிக்கவும், அல்லது இது பொருந்தாது என உறுதிசெய்யவும்.',
