    'kn': 'ನಿಮ್ಮ ದಾಖಲೆ ಉತ್ತರಗಳನ್ನು ಮುಂದಕ್ಕೆ ಒಯ್ಯಲಾಗಿದೆ. ಪ್ರತಿ ಕಾರ್ಯ ಪೂರ್ಣಗೊಂಡಾಗ ಗುರುತಿಸಿ, ಅಥವಾ ಅದು ಅನ್ವಯಿಸುವುದಿಲ್ಲ ಎಂದು ಖಚಿತಪಡಿಸಿ.',
