    'gu': 'GeM પર, Sign up → Seller પસંદ કરો, પૂર્વજરૂરિયાતો વાંચો અને તમારી પોતાની સંપર્ક વિગતોથી ખાતું બનાવો. પછી વિક્રેતા પ્રોફાઇલ અને કેટલોગ પૂર્ણ કરો.',
    'ta': 'GeM-இல், Sign up → Seller-ஐத் தேர்ந்தெடுங்கள், முன்நிபந்தனைகளைப் படித்து உங்கள் தொடர்பு விவரங்களுடன் கணக்கை உருவாக்குங்கள். பின்னர் விற்பனையாளர் சுயவிவரம் மற்றும் கேட்டலாக்கை முடிக்கவும்.',
