    'mr': 'ऐच्छिक संशोधन फॉलो-अप. स्वतंत्रपणे सत्यापित होईपर्यंत दावे स्वयं-नोंदवलेले राहतात. PAN, आधार, पासवर्ड किंवा OTP प्रविष्ट करू नका.',
