    'pa': 'ਵਿਕਲਪਿਕ ਖੋਜ ਫਾਲੋ-ਅੱਪ। ਸੁਤੰਤਰ ਤੌਰ \'ਤੇ ਪੁਸ਼ਟੀ ਹੋਣ ਤੱਕ ਦਾਅਵੇ ਖੁਦ-ਦਰਜ ਰਹਿੰਦੇ ਹਨ। PAN, ਆਧਾਰ, ਪਾਸਵਰਡ ਜਾਂ OTP ਦਰਜ ਨਾ ਕਰੋ।',
    'gu': 'વૈકલ્પિક સંશોધન ફોલો-અપ. સ્વતંત્ર રીતે ચકાસાય ત્યાં સુધી દાવા સ્વ-રિપોર્ટેડ રહે છે. PAN, આધાર, પાસવર્ડ અથવા OTP દાખલ ન કરો.',
    'ta': 'விருப்ப ஆராய்ச்சி பின்தொடர்தல். சுயாதீனமாக சரிபார்க்கும் வரை கூற்றுகள் சுய-அறிக்கையாகவே இருக்கும். PAN, ஆதார், கடவுச்சொற்கள் அல்லது OTP-களை உள்ளிட வேண்டாம்.',
    'te': 'ఐచ్ఛిక పరిశోధన ఫాలో-అప్. స్వతంత్రంగా ధృవీకరించే వరకు క్లెయిమ్‌లు స్వీయ-నివేదితంగా ఉంటాయి. PAN, ఆధార్, పాస్‌వర్డ్‌లు లేదా OTPలను నమోదు చేయవద్దు.',
    'kn': 'ಆಯ್ಕೆಯ ಸಂಶೋಧನಾ ಫಾಲೋ-ಅಪ್. ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸುವವರೆಗೆ ಹೇಳಿಕೆಗಳು ಸ್ವಯಂ-ವರದಿಯಾಗಿ ಉಳಿಯುತ್ತವೆ. PAN, ಆಧಾರ್, ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಅಥವಾ OTPಗಳನ್ನು ನಮೂದಿಸಬೇಡಿ.',
  },
