  'Could not complete this action. Check your connection and code, then try again.': {
    'mr': 'ही क्रिया पूर्ण करता आली नाही. तुमचे कनेक्शन आणि कोड तपासा, नंतर पुन्हा प्रयत्न करा.',
    'bn': 'এই কাজটি সম্পন্ন করা যায়নি। সংযোগ ও কোড যাচাই করে আবার চেষ্টা করুন।',
    'pa': 'ਇਹ ਕਾਰਵਾਈ ਪੂਰੀ ਨਹੀਂ ਹੋ ਸਕੀ। ਆਪਣਾ ਕਨੈਕਸ਼ਨ ਅਤੇ ਕੋਡ ਜਾਂਚੋ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।',
