    'ta': 'இந்தச் செயலை முடிக்க முடியவில்லை. உங்கள் இணைப்பு மற்றும் குறியீட்டைச் சரிபார்த்து மீண்டும் முயற்சிக்கவும்.',
    'te': 'ఈ చర్యను పూర్తి చేయడం సాధ్యం కాలేదు. మీ కనెక్షన్ మరియు కోడ్‌ను తనిఖీ చేసి, మళ్లీ ప్రయత్నించండి.',
    'kn': 'ಈ ಕ್ರಮವನ್ನು ಪೂರ್ಣಗೊಳಿಸಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ನಿಮ್ಮ ಸಂಪರ್ಕ ಮತ್ತು ಕೋಡ್ ಅನ್ನು ಪರಿಶೀಲಿಸಿ, ನಂತರ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
