  'Your tools work without an account. Sign in by email to keep your report across devices.': {
    'mr': 'तुमची टूल्स खाते नसतानाही काम करतात. सर्व डिव्हाइसवर तुमचा अहवाल ठेवण्यासाठी ईमेलने साइन इन करा.',
    'bn': 'আপনার সরঞ্জাম অ্যাকাউন্ট ছাড়াই কাজ করে। সব ডিভাইসে রিপোর্ট রাখতে ইমেইলে সাইন ইন করুন।',
    'pa': 'ਤੁਹਾਡੇ ਟੂਲ ਖਾਤੇ ਤੋਂ ਬਿਨਾਂ ਕੰਮ ਕਰਦੇ ਹਨ। ਸਾਰੇ ਡਿਵਾਈਸਾਂ \'ਤੇ ਰਿਪੋਰਟ ਰੱਖਣ ਲਈ ਈਮੇਲ ਨਾਲ ਸਾਈਨ ਇਨ ਕਰੋ।',
    'gu': 'તમારા ટૂલ્સ ખાતા વિના કામ કરે છે. તમામ ડિવાઇસ પર રિપોર્ટ રાખવા ઇમેઇલથી સાઇન ઇન કરો.',
    'ta': 'உங்கள் கருவிகள் கணக்கு இல்லாமலேயே செயல்படும். சாதனங்கள் முழுவதும் அறிக்கையை வைத்திருக்க மின்னஞ்சல் மூலம் சைன் இன் செய்யுங்கள்.',
    'te': 'మీ టూల్స్ ఖాతా లేకుండానే పని చేస్తాయి. అన్ని పరికరాల్లో రిపోర్ట్‌ను ఉంచుకోవడానికి ఇమెయిల్‌తో సైన్ ఇన్ చేయండి.',
    'kn': 'ನಿಮ್ಮ ಟೂಲ್‌ಗಳು ಖಾತೆ ಇಲ್ಲದೆಯೂ ಕೆಲಸ ಮಾಡುತ್ತವೆ. ಎಲ್ಲಾ ಡಿವೈಸ್‌ಗಳಲ್ಲಿ ವರದಿಯನ್ನು ಇಡಲು ಇಮೇಲ್ ಮೂಲಕ ಸೈನ್ ಇನ್ ಮಾಡಿ.',
  },
