  'Online saving is not connected yet. Your plan is saved on this device; use the report’s download or copy options to keep a portable copy.': {
    'mr': 'ऑनलाइन सेव्हिंग अजून जोडलेले नाही. तुमची योजना या डिव्हाइसवर सेव्ह आहे; पोर्टेबल कॉपी ठेवण्यासाठी अहवालाचे डाउनलोड किंवा कॉपी पर्याय वापरा.',
    'bn': 'অনলাইন সংরক্ষণ এখনো সংযুক্ত নয়। আপনার পরিকল্পনা এই ডিভাইসে সংরক্ষিত; একটি বহনযোগ্য কপি রাখতে রিপোর্টের ডাউনলোড বা কপি অপশন ব্যবহার করুন।',
