    'kn': 'ನೀವು ಏನನ್ನು ಹಂಚಿಕೊಳ್ಳುತ್ತೀರಿ ಎಂಬುದನ್ನು ನೀವೇ ನಿಯಂತ್ರಿಸುತ್ತೀರಿ',
  },
  'We save calculator answers and progress locally. If you sign in, they are saved in Supabase under your account. We do not ask for document scans, Aadhaar or PAN numbers.': {
    'mr': 'आम्ही कॅल्क्युलेटरची उत्तरे आणि प्रगती स्थानिक पातळीवर सेव्ह करतो. साइन इन केल्यास, ती तुमच्या खात्याखाली Supabase मध्ये सेव्ह होतात. आम्ही कागदपत्र स्कॅन, आधार किंवा PAN नंबर मागत नाही.',
    'bn': 'আমরা ক্যালকুলেটরের উত্তর ও অগ্রগতি স্থানীয়ভাবে সংরক্ষণ করি। সাইন ইন করলে, তা আপনার অ্যাকাউন্টের অধীনে Supabase-এ সংরক্ষিত হয়। আমরা ডকুমেন্ট স্ক্যান, আধার বা PAN নম্বর চাই না।',
    'pa': 'ਅਸੀਂ ਕੈਲਕੁਲੇਟਰ ਦੇ ਜਵਾਬ ਅਤੇ ਪ੍ਰਗਤੀ ਸਥਾਨਕ ਤੌਰ \'ਤੇ ਸੇਵ ਕਰਦੇ ਹਾਂ। ਸਾਈਨ ਇਨ ਕਰਨ \'ਤੇ, ਇਹ ਤੁਹਾਡੇ ਖਾਤੇ ਹੇਠ Supabase ਵਿੱਚ ਸੇਵ ਹੁੰਦੇ ਹਨ। ਅਸੀਂ ਦਸਤਾਵੇਜ਼ ਸਕੈਨ, ਆਧਾਰ ਜਾਂ PAN ਨੰਬਰ ਨਹੀਂ ਮੰਗਦੇ।',
    'gu': 'અમે કેલ્ક્યુલેટરના જવાબો અને પ્રગતિ સ્થાનિક રીતે સેવ કરીએ છીએ. સાઇન ઇન કરો તો, તે તમારા ખાતા હેઠળ Supabase માં સેવ થાય છે. અમે દસ્તાવેજ સ્કેન, આધાર અથવા PAN નંબર માંગતા નથી.',
    'ta': 'நாங்கள் கால்குலேட்டர் பதில்கள் மற்றும் முன்னேற்றத்தை உள்ளூரில் சேமிக்கிறோம். சைன் இன் செய்தால், அவை உங்கள் கணக்கின் கீழ் Supabase-இல் சேமிக்கப்படும். ஆவண ஸ்கேன்கள், ஆதார் அல்லது PAN எண்களை நாங்கள் கேட்பதில்லை.',
    'te': 'మేము కాలిక్యులేటర్ సమాధానాలు మరియు ప్రోగ్రెస్‌ను స్థానికంగా సేవ్ చేస్తాము. మీరు సైన్ ఇన్ చేస్తే, అవి మీ ఖాతా క్రింద Supabaseలో సేవ్ చేయబడతాయి. మేము డాక్యుమెంట్ స్కాన్‌లు, ఆధార్ లేదా PAN నంబర్‌లను అడగము.',
    'kn': 'ನಾವು ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಉತ್ತರಗಳು ಮತ್ತು ಪ್ರಗತಿಯನ್ನು ಸ್ಥಳೀಯವಾಗಿ ಉಳಿಸುತ್ತೇವೆ. ನೀವು ಸೈನ್ ಇನ್ ಮಾಡಿದರೆ, ಅವು ನಿಮ್ಮ ಖಾತೆಯ ಅಡಿಯಲ್ಲಿ Supabase ನಲ್ಲಿ ಉಳಿಯುತ್ತವೆ. ನಾವು ದಾಖಲೆ ಸ್ಕ್ಯಾನ್‌ಗಳು, ಆಧಾರ್ ಅಥವಾ PAN ಸಂಖ್ಯೆಗಳನ್ನು ಕೇಳುವುದಿಲ್ಲ.',
  },
  'Help improve this research project': {
    'mr': 'हा संशोधन प्रकल्प सुधारण्यास मदत करा',
    'bn': 'এই গবেষণা প্রকল্প উন্নত করতে সাহায্য করুন',
    'pa': 'ਇਸ ਖੋਜ ਪ੍ਰੋਜੈਕਟ ਨੂੰ ਬਿਹਤਰ ਬਣਾਉਣ ਵਿੱਚ ਮਦਦ ਕਰੋ',
    'gu': 'આ સંશોધન પ્રોજેક્ટને સુધારવામાં મદદ કરો',
    'ta': 'இந்த ஆராய்ச்சி திட்டத்தை மேம்படுத்த உதவுங்கள்',
    'te': 'ఈ పరిశోధన ప్రాజెక్ట్‌ను మెరుగుపరచడంలో సహాయపడండి',
    'kn': 'ಈ ಸಂಶೋಧನಾ ಯೋಜನೆಯನ್ನು ಸುಧಾರಿಸಲು ಸಹಾಯ ಮಾಡಿ',
  },
  'Optional: record tool usage, active time, referral source and funnel steps. Uploaded only when signed in. No financial inputs in event properties.': {
    'mr': 'ऐच्छिक: टूल वापर, सक्रिय वेळ, रेफरल स्रोत आणि फनेल पायऱ्या नोंदवा. साइन इन केल्यावरच अपलोड होते. इव्हेंट प्रॉपर्टीजमध्ये आर्थिक इनपुट नाही.',
    'bn': 'ঐচ্ছিক: টুল ব্যবহার, সক্রিয় সময়, রেফারেল সোর্স ও ফানেল পদক্ষেপ রেকর্ড করুন। সাইন ইন করা থাকলেই আপলোড হয়। ইভেন্ট প্রপার্টিতে কোনো আর্থিক ইনপুট নেই।',
    'pa': 'ਵਿਕਲਪਿਕ: ਟੂਲ ਵਰਤੋਂ, ਸਰਗਰਮ ਸਮਾਂ, ਰੈਫਰਲ ਸਰੋਤ ਅਤੇ ਫਨਲ ਕਦਮ ਰਿਕਾਰਡ ਕਰੋ। ਸਿਰਫ਼ ਸਾਈਨ ਇਨ ਹੋਣ \'ਤੇ ਅੱਪਲੋਡ ਹੁੰਦਾ ਹੈ। ਇਵੈਂਟ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ ਵਿੱਚ ਕੋਈ ਵਿੱਤੀ ਇਨਪੁੱਟ ਨਹੀਂ।',
    'gu': 'વૈકલ્પિક: ટૂલ ઉપયોગ, સક્રિય સમય, રેફરલ સ્રોત અને ફનલ પગલાં રેકોર્ડ કરો. સાઇન ઇન હોય ત્યારે જ અપલોડ થાય છે. ઇવેન્ટ પ્રોપર્ટીમાં કોઈ નાણાકીય ઇનપુટ નથી.',
    'ta': 'விருப்பம்: கருவி பயன்பாடு, செயலில் நேரம், பரிந்துரை மூலம் மற்றும் ஃபன்னல் படிகளைப் பதிவு செய்யுங்கள். சைன் இன் செய்யும்போது மட்டுமே பதிவேற்றப்படும். நிகழ்வு பண்புகளில் நிதி உள்ளீடுகள் இல்லை.',
    'te': 'ఐచ్ఛికం: టూల్ వాడకం, యాక్టివ్ సమయం, రెఫరల్ మూలం మరియు ఫన్నెల్ దశలను రికార్డ్ చేయండి. సైన్ ఇన్ అయినప్పుడు మాత్రమే అప్‌లోడ్ అవుతుంది. ఈవెంట్ ప్రాపర్టీలలో ఆర్థిక ఇన్‌పుట్‌లు లేవు.',
    'kn': 'ಆಯ್ಕೆಯ: ಟೂಲ್ ಬಳಕೆ, ಸಕ್ರಿಯ ಸಮಯ, ರೆಫರಲ್ ಮೂಲ ಮತ್ತು ಫನಲ್ ಹಂತಗಳನ್ನು ರೆಕಾರ್ಡ್ ಮಾಡಿ. ಸೈನ್ ಇನ್ ಆಗಿದ್ದಾಗ ಮಾತ್ರ ಅಪ್‌ಲೋಡ್ ಆಗುತ್ತದೆ. ಈವೆಂಟ್ ಪ್ರಾಪರ್ಟಿಗಳಲ್ಲಿ ಆರ್ಥಿಕ ಇನ್‌ಪುಟ್‌ಗಳಿಲ್ಲ.',
  },
  'Turning this off stops new research events and clears unsent events. Previously uploaded events remain until you delete your project data. CA sharing requires separate consent in a support request.': {
    'mr': 'हे बंद केल्याने नवीन संशोधन इव्हेंट थांबतात आणि न पाठवलेले इव्हेंट साफ होतात. आधी अपलोड केलेले इव्हेंट तुम्ही प्रकल्प डेटा डिलीट करेपर्यंत राहतात. CA सोबत शेअरिंगसाठी सपोर्ट रिक्वेस्टमध्ये स्वतंत्र सहमती आवश्यक आहे.',
    'bn': 'এটি বন্ধ করলে নতুন গবেষণা ইভেন্ট বন্ধ হয় এবং অপ্রেরিত ইভেন্ট মুছে যায়। আগে আপলোড করা ইভেন্ট আপনি প্রকল্পের ডেটা মুছে না দেওয়া পর্যন্ত থাকে। CA শেয়ারিংয়ের জন্য সহায়তা অনুরোধে পৃথক সম্মতি প্রয়োজন।',
    'pa': 'ਇਹ ਬੰਦ ਕਰਨ ਨਾਲ ਨਵੇਂ ਖੋਜ ਇਵੈਂਟ ਰੁਕ ਜਾਂਦੇ ਹਨ ਅਤੇ ਨਾ ਭੇਜੇ ਇਵੈਂਟ ਸਾਫ਼ ਹੋ ਜਾਂਦੇ ਹਨ। ਪਹਿਲਾਂ ਅੱਪਲੋਡ ਕੀਤੇ ਇਵੈਂਟ ਉਦੋਂ ਤੱਕ ਰਹਿੰਦੇ ਹਨ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਆਪਣਾ ਪ੍ਰੋਜੈਕਟ ਡਾਟਾ ਨਹੀਂ ਮਿਟਾਉਂਦੇ। CA ਸਾਂਝਾ ਕਰਨ ਲਈ ਸਹਾਇਤਾ ਬੇਨਤੀ ਵਿੱਚ ਵੱਖਰੀ ਸਹਿਮਤੀ ਲੋੜੀਂਦੀ ਹੈ।',
    'gu': 'આ બંધ કરવાથી નવા સંશોધન ઇવેન્ટ અટકે છે અને ન મોકલાયેલા ઇવેન્ટ સાફ થાય છે. અગાઉ અપલોડ કરેલા ઇવેન્ટ તમે પ્રોજેક્ટ ડેટા ડિલીટ ન કરો ત્યાં સુધી રહે છે. CA શેરિંગ માટે સપોર્ટ રિક્વેસ્ટમાં અલગ સંમતિ જરૂરી છે.',
    'ta': 'இதை நிறுத்துவது புதிய ஆராய்ச்சி நிகழ்வுகளை நிறுத்தி, அனுப்பப்படாத நிகழ்வுகளை அழிக்கும். முன்பு பதிவேற்றப்பட்ட நிகழ்வுகள் நீங்கள் திட்ட தரவை நீக்கும் வரை இருக்கும். CA பகிர்வுக்கு ஆதரவு கோரிக்கையில் தனி ஒப்புதல் தேவை.',
    'te': 'దీన్ని ఆఫ్ చేయడం కొత్త పరిశోధన ఈవెంట్‌లను ఆపి, పంపని ఈవెంట్‌లను క్లియర్ చేస్తుంది. మీరు ప్రాజెక్ట్ డేటాను తొలగించే వరకు మునుపు అప్‌లోడ్ చేసిన ఈవెంట్‌లు ఉంటాయి. CA షేరింగ్‌కు సపోర్ట్ రిక్వెస్ట్‌లో వేరే సమ్మతి అవసరం.',
    'kn': 'ಇದನ್ನು ಆಫ್ ಮಾಡುವುದರಿಂದ ಹೊಸ ಸಂಶೋಧನಾ ಈವೆಂಟ್‌ಗಳು ನಿಲ್ಲುತ್ತವೆ ಮತ್ತು ಕಳುಹಿಸದ ಈವೆಂಟ್‌ಗಳು ಅಳಿಸಲ್ಪಡುತ್ತವೆ. ನೀವು ಪ್ರಾಜೆಕ್ಟ್ ಡೇಟಾವನ್ನು ಅಳಿಸುವವರೆಗೆ ಈ ಹಿಂದೆ ಅಪ್‌ಲೋಡ್ ಮಾಡಿದ ಈವೆಂಟ್‌ಗಳು ಉಳಿಯುತ್ತವೆ. CA ಹಂಚಿಕೆಗೆ ಸಪೋರ್ಟ್ ರಿಕ್ವೆಸ್ಟ್‌ನಲ್ಲಿ ಪ್ರತ್ಯೇಕ ಒಪ್ಪಿಗೆ ಬೇಕಾಗುತ್ತದೆ.',
  },
  'Delete your project data?': {
    'mr': 'तुमचा प्रकल्प डेटा डिलीट करायचा?',
    'bn': 'আপনার প্রকল্পের ডেটা মুছে ফেলবেন?',
    'pa': 'ਆਪਣਾ ਪ੍ਰੋਜੈਕਟ ਡਾਟਾ ਮਿਟਾਉਣਾ ਹੈ?',
    'gu': 'તમારો પ્રોજેક્ટ ડેટા ડિલીટ કરવો છે?',
    'ta': 'உங்கள் திட்ட தரவை நீக்கவா?',
    'te': 'మీ ప్రాజెక్ట్ డేటాను తొలగించాలా?',
    'kn': 'ನಿಮ್ಮ ಪ್ರಾಜೆಕ್ಟ್ ಡೇಟಾವನ್ನು ಅಳಿಸಬೇಕೇ?',
  },
  'This removes this account’s plan, research events, support requests and outcomes from the project, plus this device’s saved plan. Your sign-in account remains. This cannot be undone.': {
    'mr': 'यामुळे या खात्याची योजना, संशोधन इव्हेंट, सपोर्ट रिक्वेस्ट आणि परिणाम प्रकल्पातून काढले जातात, तसेच या डिव्हाइसवरील सेव्ह केलेली योजना देखील. तुमचे साइन-इन खाते राहते. हे परत केले जाऊ शकत नाही.',
    'bn': 'এতে এই অ্যাকাউন্টের পরিকল্পনা, গবেষণা ইভেন্ট, সহায়তা অনুরোধ ও ফলাফল প্রকল্প থেকে মুছে যায়, সাথে এই ডিভাইসের সংরক্ষিত পরিকল্পনাও। আপনার সাইন-ইন অ্যাকাউন্ট থাকবে। এটি ফিরিয়ে আনা যাবে না।',
    'pa': 'ਇਹ ਇਸ ਖਾਤੇ ਦੀ ਯੋਜਨਾ, ਖੋਜ ਇਵੈਂਟ, ਸਹਾਇਤਾ ਬੇਨਤੀਆਂ ਅਤੇ ਨਤੀਜੇ ਪ੍ਰੋਜੈਕਟ ਤੋਂ ਹਟਾਉਂਦਾ ਹੈ, ਨਾਲ ਹੀ ਇਸ ਡਿਵਾਈਸ ਦੀ ਸੇਵ ਕੀਤੀ ਯੋਜਨਾ ਵੀ। ਤੁਹਾਡਾ ਸਾਈਨ-ਇਨ ਖਾਤਾ ਰਹਿੰਦਾ ਹੈ। ਇਹ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।',
    'gu': 'આ આ ખાતાની યોજના, સંશોધન ઇવેન્ટ, સપોર્ટ રિક્વેસ્ટ અને પરિણામો પ્રોજેક્ટમાંથી દૂર કરે છે, ઉપરાંત આ ડિવાઇસની સેવ કરેલી યોજના પણ. તમારું સાઇન-ઇન ખાતું રહે છે. આ પાછું લાવી શકાતું નથી.',
    'ta': 'இது இந்தக் கணக்கின் திட்டம், ஆராய்ச்சி நிகழ்வுகள், ஆதரவு கோரிக்கைகள் மற்றும் முடிவுகளை திட்டத்திலிருந்து அகற்றும், மேலும் இந்தச் சாதனத்தின் சேமிக்கப்பட்ட திட்டத்தையும். உங்கள் சைன்-இன் கணக்கு தொடரும். இதை மாற்ற முடியாது.',
    'te': 'ఇది ఈ ఖాతా ప్రణాళిక, పరిశోధన ఈవెంట్‌లు, సపోర్ట్ రిక్వెస్ట్‌లు మరియు ఫలితాలను ప్రాజెక్ట్ నుండి తొలగిస్తుంది, అలాగే ఈ పరికరం సేవ్ చేసిన ప్రణాళికను కూడా. మీ సైన్-ఇన్ ఖాతా ఉంటుంది. దీన్ని తిప్పికొట్టడం సాధ్యం కాదు.',
    'kn': 'ಇದು ಈ ಖಾತೆಯ ಯೋಜನೆ, ಸಂಶೋಧನಾ ಈವೆಂಟ್‌ಗಳು, ಸಪೋರ್ಟ್ ರಿಕ್ವೆಸ್ಟ್‌ಗಳು ಮತ್ತು ಫಲಿತಾಂಶಗಳನ್ನು ಪ್ರಾಜೆಕ್ಟ್‌ನಿಂದ ತೆಗೆದುಹಾಕುತ್ತದೆ, ಜೊತೆಗೆ ಈ ಡಿವೈಸ್‌ನ ಉಳಿಸಿದ ಯೋಜನೆಯನ್ನೂ. ನಿಮ್ಮ ಸೈನ್-ಇನ್ ಖಾತೆ ಉಳಿಯುತ್ತದೆ. ಇದನ್ನು ಹಿಂತಿರುಗಿಸಲಾಗುವುದಿಲ್ಲ.',
  },
