  'The project may contact me about this request. For a CA referral, it may share my email and this note with a partner.': {
    'mr': 'प्रकल्प या विनंतीसंबंधी माझ्याशी संपर्क करू शकतो. CA संदर्भासाठी, तो माझा ईमेल आणि ही नोंद पार्टनरसोबत शेअर करू शकतो.',
    'bn': 'এই অনুরোধ সম্পর্কে প্রকল্প আমার সাথে যোগাযোগ করতে পারে। CA রেফারেলের জন্য, এটি আমার ইমেইল ও এই নোট একজন পার্টনারের সাথে শেয়ার করতে পারে।',
    'pa': 'ਪ੍ਰੋਜੈਕਟ ਇਸ ਬੇਨਤੀ ਬਾਰੇ ਮੇਰੇ ਨਾਲ ਸੰਪਰਕ ਕਰ ਸਕਦਾ ਹੈ। CA ਸਿਫਾਰਸ਼ ਲਈ, ਇਹ ਮੇਰੀ ਈਮੇਲ ਅਤੇ ਇਹ ਨੋਟ ਕਿਸੇ ਪਾਰਟਨਰ ਨਾਲ ਸਾਂਝਾ ਕਰ ਸਕਦਾ ਹੈ।',
    'gu': 'આ વિનંતી વિશે પ્રોજેક્ટ મારો સંપર્ક કરી શકે છે. CA રેફરલ માટે, તે મારો ઇમેઇલ અને આ નોંધ પાર્ટનર સાથે શેર કરી શકે છે.',
    'ta': 'இந்தக் கோரிக்கை பற்றி திட்டம் என்னைத் தொடர்பு கொள்ளலாம். CA பரிந்துரைக்கு, அது எனது மின்னஞ்சல் மற்றும் இந்த குறிப்பை ஒரு பார்ட்னருடன் பகிரலாம்.',
    'te': 'ఈ రిక్వెస్ట్ గురించి ప్రాజెక్ట్ నన్ను సంప్రదించవచ్చు. CA రెఫరల్ కోసం, అది నా ఇమెయిల్ మరియు ఈ నోట్‌ను ఒక పార్టనర్‌తో షేర్ చేయవచ్చు.',
    'kn': 'ಈ ರಿಕ್ವೆಸ್ಟ್ ಬಗ್ಗೆ ಪ್ರಾಜೆಕ್ಟ್ ನನ್ನನ್ನು ಸಂಪರ್ಕಿಸಬಹುದು. CA ರೆಫರಲ್‌ಗಾಗಿ, ಅದು ನನ್ನ ಇಮೇಲ್ ಮತ್ತು ಈ ಟಿಪ್ಪಣಿಯನ್ನು ಪಾರ್ಟನರ್‌ನೊಂದಿಗೆ ಹಂಚಿಕೊಳ್ಳಬಹುದು.',
  },
  'Add a short note and consent to follow-up.': {
    'mr': 'एक छोटी नोंद जोडा आणि फॉलो-अपसाठी सहमती द्या.',
    'bn': 'একটি সংক্ষিপ্ত নোট যোগ করুন এবং ফলো-আপে সম্মতি দিন।',
    'pa': 'ਇੱਕ ਛੋਟਾ ਨੋਟ ਸ਼ਾਮਲ ਕਰੋ ਅਤੇ ਫਾਲੋ-ਅੱਪ ਲਈ ਸਹਿਮਤੀ ਦਿਓ।',
    'gu': 'એક ટૂંકી નોંધ ઉમેરો અને ફોલો-અપ માટે સંમતિ આપો.',
    'ta': 'ஒரு சிறு குறிப்பைச் சேர்த்து பின்தொடர்தலுக்கு ஒப்புதல் தெரிவிக்கவும்.',
    'te': 'ఒక చిన్న నోట్‌ను జోడించి ఫాలో-అప్‌కు సమ్మతి తెలియజేయండి.',
    'kn': 'ಒಂದು ಚಿಕ್ಕ ಟಿಪ್ಪಣಿಯನ್ನು ಸೇರಿಸಿ ಮತ್ತು ಫಾಲೋ-ಅಪ್‌ಗೆ ಒಪ್ಪಿಗೆ ನೀಡಿ.',
  },
  'Request received. No workshop date or partner appointment is confirmed yet.': {
    'mr': 'विनंती मिळाली. अजून कार्यशाळेची तारीख किंवा पार्टनर भेट निश्चित नाही.',
    'bn': 'অনুরোধ পাওয়া গেছে। কোনো কর্মশালার তারিখ বা পার্টনার অ্যাপয়েন্টমেন্ট এখনো নিশ্চিত নয়।',
    'pa': 'ਬੇਨਤੀ ਮਿਲੀ। ਅਜੇ ਕੋਈ ਵਰਕਸ਼ਾਪ ਤਾਰੀਖ ਜਾਂ ਪਾਰਟਨਰ ਮੁਲਾਕਾਤ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋਈ।',
    'gu': 'વિનંતી મળી. હજુ કોઈ વર્કશોપ તારીખ અથવા પાર્ટનર એપોઇન્ટમેન્ટ નિશ્ચિત નથી.',
    'ta': 'கோரிக்கை பெறப்பட்டது. இன்னும் பட்டறை தேதி அல்லது பார்ட்னர் நேரம் உறுதி செய்யப்படவில்லை.',
    'te': 'రిక్వెస్ట్ అందింది. ఇంకా వర్క్‌షాప్ తేదీ లేదా పార్టనర్ అపాయింట్‌మెంట్ నిర్ధారించబడలేదు.',
    'kn': 'ರಿಕ್ವೆಸ್ಟ್ ಸ್ವೀಕರಿಸಲಾಗಿದೆ. ಇನ್ನೂ ಯಾವುದೇ ಕಾರ್ಯಾಗಾರ ದಿನಾಂಕ ಅಥವಾ ಪಾರ್ಟನರ್ ಅಪಾಯಿಂಟ್‌ಮೆಂಟ್ ದೃಢಪಟ್ಟಿಲ್ಲ.',
  },
  'Request not sent. Please retry when connected.': {
    'mr': 'विनंती पाठवली गेली नाही. कनेक्ट झाल्यावर पुन्हा प्रयत्न करा.',
    'bn': 'অনুরোধ পাঠানো হয়নি। সংযোগ থাকলে আবার চেষ্টা করুন।',
    'pa': 'ਬੇਨਤੀ ਨਹੀਂ ਭੇਜੀ ਗਈ। ਕਨੈਕਟ ਹੋਣ \'ਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।',
    'gu': 'વિનંતી મોકલાઈ નથી. કનેક્ટ થાય ત્યારે ફરી પ્રયાસ કરો.',
    'ta': 'கோரிக்கை அனுப்பப்படவில்லை. இணைப்பு கிடைத்தபோது மீண்டும் முயற்சிக்கவும்.',
    'te': 'రిక్వెస్ట్ పంపబడలేదు. కనెక్ట్ అయినప్పుడు మళ్లీ ప్రయత్నించండి.',
    'kn': 'ರಿಕ್ವೆಸ್ಟ್ ಕಳುಹಿಸಲಾಗಿಲ್ಲ. ಸಂಪರ್ಕಗೊಂಡಾಗ ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.',
  },
