  'Workshops and CA availability will be confirmed by the project team. Submitting interest does not book a place or guarantee an order.': {
    'mr': 'कार्यशाळा आणि CA उपलब्धता प्रकल्प टीम निश्चित करेल. रुची सबमिट केल्याने जागा बुक होत नाही किंवा ऑर्डरची खात्री मिळत नाही.',
    'bn': 'কর্মশালা ও CA প্রাপ্যতা প্রকল্প দল নিশ্চিত করবে। আগ্রহ জমা দেওয়া কোনো স্থান বুক করে না বা অর্ডারের নিশ্চয়তা দেয় না।',
    'pa': 'ਵਰਕਸ਼ਾਪ ਅਤੇ CA ਉਪਲਬਧਤਾ ਪ੍ਰੋਜੈਕਟ ਟੀਮ ਦੁਆਰਾ ਪੁਸ਼ਟੀ ਕੀਤੀ ਜਾਵੇਗੀ। ਦਿਲਚਸਪੀ ਜਮ੍ਹਾਂ ਕਰਨ ਨਾਲ ਕੋਈ ਥਾਂ ਬੁੱਕ ਨਹੀਂ ਹੁੰਦੀ ਜਾਂ ਆਰਡਰ ਦੀ ਗਰੰਟੀ ਨਹੀਂ ਹੁੰਦੀ।',
    'gu': 'વર્કશોપ અને CA ઉપલબ્ધતા પ્રોજેક્ટ ટીમ દ્વારા પુષ્ટિ કરવામાં આવશે. રસ સબમિટ કરવાથી કોઈ સ્થાન બુક થતું નથી અથવા ઓર્ડરની ગેરંટી મળતી નથી.',
    'ta': 'பட்டறை மற்றும் CA கிடைப்பது திட்டக் குழுவால் உறுதி செய்யப்படும். ஆர்வத்தை சமர்ப்பிப்பது ஒரு இடத்தை பதிவு செய்யாது அல்லது ஆர்டரை உத்தரவாதம் செய்யாது.',
    'te': 'వర్క్‌షాప్ మరియు CA లభ్యతను ప్రాజెక్ట్ బృందం నిర్ధారిస్తుంది. ఆసక్తిని సమర్పించడం ఒక స్థానాన్ని బుక్ చేయదు లేదా ఆర్డర్‌కు హామీ ఇవ్వదు.',
    'kn': 'ಕಾರ್ಯಾಗಾರ ಮತ್ತು CA ಲಭ್ಯತೆಯನ್ನು ಪ್ರಾಜೆಕ್ಟ್ ತಂಡ ದೃಢೀಕರಿಸುತ್ತದೆ. ಆಸಕ್ತಿ ಸಲ್ಲಿಸುವುದು ಒಂದು ಸ್ಥಳವನ್ನು ಬುಕ್ ಮಾಡುವುದಿಲ್ಲ ಅಥವಾ ಆರ್ಡರ್‌ಗೆ ಖಾತ್ರಿ ನೀಡುವುದಿಲ್ಲ.',
  },
