  'An independent entrepreneurship and financial empowerment project led by Amay, focused on Pune and Maharashtra SMEs.': {
    'mr': 'अमय यांच्या नेतृत्वाखालील, पुणे आणि महाराष्ट्रातील SME वर केंद्रित एक स्वतंत्र उद्योजकता आणि आर्थिक सशक्तीकरण प्रकल्प.',
    'bn': 'অময়ের নেতৃত্বে, পুনে ও মহারাষ্ট্রের SME-কেন্দ্রিক একটি স্বাধীন উদ্যোক্তা ও আর্থিক ক্ষমতায়ন প্রকল্প।',
    'pa': 'ਅਮੇ ਦੀ ਅਗਵਾਈ ਹੇਠ, ਪੂਨੇ ਅਤੇ ਮਹਾਰਾਸ਼ਟਰ ਦੇ SME \'ਤੇ ਕੇਂਦ੍ਰਿਤ ਇੱਕ ਸੁਤੰਤਰ ਉੱਦਮਤਾ ਅਤੇ ਵਿੱਤੀ ਸਸ਼ਕਤੀਕਰਨ ਪ੍ਰੋਜੈਕਟ।',
    'gu': 'અમય દ્વારા સંચાલિત, પુણે અને મહારાષ્ટ્રના SME પર કેન્દ્રિત એક સ્વતંત્ર ઉદ્યોગસાહસિકતા અને નાણાકીય સશક્તિકરણ પ્રોજેક્ટ.',
    'ta': 'அமய் தலைமையிலான, புனே மற்றும் மகாராஷ்டிரா SME-களை மையமாகக் கொண்ட ஒரு சுயாதீன தொழில்முனைவு மற்றும் நிதி அதிகாரமளிப்பு திட்டம்.',
    'te': 'అమయ్ నేతృత్వంలో, పూణే మరియు మహారాష్ట్ర SMEలపై దృష్టి సారించిన స్వతంత్ర వ్యవస్థాపకత మరియు ఆర్థిక సాధికారత ప్రాజెక్ట్.',
    'kn': 'ಅಮಯ್ ನೇತೃತ್ವದ, ಪುಣೆ ಮತ್ತು ಮಹಾರಾಷ್ಟ್ರದ SME ಗಳ ಮೇಲೆ ಕೇಂದ್ರೀಕರಿಸಿದ ಸ್ವತಂತ್ರ ಉದ್ಯಮಶೀಲತೆ ಮತ್ತು ಆರ್ಥಿಕ ಸಶಕ್ತೀಕರಣ ಯೋಜನೆ.',
  },
  'Research informs the tools': {
    'mr': 'संशोधन टूल्सला दिशा देते',
    'bn': 'গবেষণা টুলগুলোকে জানায়',
    'pa': 'ਖੋਜ ਟੂਲਾਂ ਨੂੰ ਜਾਣਕਾਰੀ ਦਿੰਦੀ ਹੈ',
    'gu': 'સંશોધન ટૂલ્સને માહિતગાર કરે છે',
    'ta': 'ஆராய்ச்சி கருவிகளுக்கு தகவல் தருகிறது',
    'te': 'పరిశోధన టూల్స్‌ను తెలియజేస్తుంది',
    'kn': 'ಸಂಶೋಧನೆ ಟೂಲ್‌ಗಳಿಗೆ ಮಾಹಿತಿ ನೀಡುತ್ತದೆ',
  },
  'The supplied project brief describes a 20-owner diagnostic survey. Eligibility uncertainty and low confidence about revenue and effort inform this journey. Raw survey data, dates and interview timing evidence have not yet been supplied; survey figures are provisional project inputs.': {
    'mr': 'दिलेल्या प्रकल्प संक्षिप्तात 20-मालकांच्या डायग्नोस्टिक सर्वेक्षणाचे वर्णन आहे. पात्रतेतील अनिश्चितता आणि उत्पन्न व प्रयत्नांबद्दल कमी आत्मविश्वास या प्रवासाला दिशा देतात. मूळ सर्वेक्षण डेटा, तारखा आणि मुलाखतीच्या वेळेचा पुरावा अद्याप दिलेला नाही; सर्वेक्षण आकडे तात्पुरते प्रकल्प इनपुट आहेत.',
    'bn': 'সরবরাহকৃত প্রকল্প সংক্ষিপ্তে ২০-মালিকের ডায়াগনস্টিক সমীক্ষার বর্ণনা আছে। যোগ্যতার অনিশ্চয়তা এবং আয় ও প্রচেষ্টা নিয়ে কম আত্মবিশ্বাস এই যাত্রাকে নির্দেশ করে। কাঁচা সমীক্ষা তথ্য, তারিখ ও সাক্ষাৎকারের সময়ের প্রমাণ এখনো দেওয়া হয়নি; সমীক্ষার সংখ্যা সাময়িক প্রকল্প ইনপুট।',
    'pa': 'ਦਿੱਤੇ ਗਏ ਪ੍ਰੋਜੈਕਟ ਸੰਖੇਪ ਵਿੱਚ 20-ਮਾਲਕਾਂ ਦੇ ਡਾਇਗਨੋਸਟਿਕ ਸਰਵੇ ਦਾ ਵਰਣਨ ਹੈ। ਯੋਗਤਾ ਦੀ ਅਨਿਸ਼ਚਿਤਤਾ ਅਤੇ ਆਮਦਨ ਤੇ ਯਤਨ ਬਾਰੇ ਘੱਟ ਭਰੋਸਾ ਇਸ ਸਫ਼ਰ ਨੂੰ ਸੇਧ ਦਿੰਦੇ ਹਨ। ਕੱਚਾ ਸਰਵੇ ਡਾਟਾ, ਤਾਰੀਖਾਂ ਅਤੇ ਇੰਟਰਵਿਊ ਸਮੇਂ ਦਾ ਸਬੂਤ ਅਜੇ ਨਹੀਂ ਦਿੱਤਾ ਗਿਆ; ਸਰਵੇ ਅੰਕੜੇ ਆਰਜ਼ੀ ਪ੍ਰੋਜੈਕਟ ਇਨਪੁੱਟ ਹਨ।',
    'gu': 'આપેલા પ્રોજેક્ટ સંક્ષિપ્તમાં 20-માલિકોના ડાયગ્નોસ્ટિક સર્વેનું વર્ણન છે. પાત્રતાની અનિશ્ચિતતા અને આવક તથા પ્રયત્ન વિશે ઓછો વિશ્વાસ આ યાત્રાને દિશા આપે છે. કાચો સર્વે ડેટા, તારીખો અને ઇન્ટરવ્યૂ સમયનો પુરાવો હજુ આપ્યો નથી; સર્વે આંકડા હંગામી પ્રોજેક્ટ ઇનપુટ છે.',
    'ta': 'வழங்கப்பட்ட திட்டச் சுருக்கம் 20-உரிமையாளர் நோயறிதல் கணக்கெடுப்பை விவரிக்கிறது. தகுதி நிச்சயமற்ற தன்மை மற்றும் வருமானம் & முயற்சி பற்றிய குறைந்த நம்பிக்கை இந்தப் பயணத்திற்கு வழிகாட்டுகிறது. மூல கணக்கெடுப்பு தரவு, தேதிகள் மற்றும் நேர்காணல் நேர ஆதாரம் இன்னும் வழங்கப்படவில்லை; கணக்கெடுப்பு எண்கள் தற்காலிக திட்ட உள்ளீடுகள்.',
    'te': 'అందించిన ప్రాజెక్ట్ బ్రీఫ్ 20-యజమాని డయాగ్నస్టిక్ సర్వేను వివరిస్తుంది. అర్హత అనిశ్చితి మరియు ఆదాయం & శ్రమపై తక్కువ నమ్మకం ఈ ప్రయాణానికి మార్గనిర్దేశం చేస్తాయి. ముడి సర్వే డేటా, తేదీలు మరియు ఇంటర్వ్యూ సమయ ఆధారాలు ఇంకా అందించబడలేదు; సర్వే గణాంకాలు తాత్కాలిక ప్రాజెక్ట్ ఇన్‌పుట్‌లు.',
    'kn': 'ಒದಗಿಸಲಾದ ಪ್ರಾಜೆಕ್ಟ್ ಸಾರಾಂಶ 20-ಮಾಲೀಕರ ರೋಗನಿರ್ಣಯ ಸಮೀಕ್ಷೆಯನ್ನು ವಿವರಿಸುತ್ತದೆ. ಅರ್ಹತೆಯ ಅನಿಶ್ಚಿತತೆ ಮತ್ತು ಆದಾಯ ಮತ್ತು ಪ್ರಯತ್ನದ ಬಗ್ಗೆ ಕಡಿಮೆ ವಿಶ್ವಾಸ ಈ ಪ್ರಯಾಣಕ್ಕೆ ಮಾರ್ಗದರ್ಶನ ನೀಡುತ್ತದೆ. ಕಚ್ಚಾ ಸಮೀಕ್ಷೆ ಡೇಟಾ, ದಿನಾಂಕಗಳು ಮತ್ತು ಸಂದರ್ಶನ ಸಮಯದ ಪುರಾವೆ ಇನ್ನೂ ಒದಗಿಸಲಾಗಿಲ್ಲ; ಸಮೀಕ್ಷೆ ಅಂಕಿಅಂಶಗಳು ತಾತ್ಕಾಲಿಕ ಪ್ರಾಜೆಕ್ಟ್ ಇನ್‌ಪುಟ್‌ಗಳಾಗಿವೆ.',
  },
  'What the tools can tell you': {
    'mr': 'टूल्स तुम्हाला काय सांगू शकतात',
    'bn': 'টুলগুলো আপনাকে যা বলতে পারে',
    'pa': 'ਟੂਲ ਤੁਹਾਨੂੰ ਕੀ ਦੱਸ ਸਕਦੇ ਹਨ',
    'gu': 'ટૂલ્સ તમને શું જણાવી શકે છે',
    'ta': 'கருவிகள் உங்களுக்குச் சொல்லக்கூடியது',
    'te': 'టూల్స్ మీకు ఏమి చెప్పగలవు',
    'kn': 'ಟೂಲ್‌ಗಳು ನಿಮಗೆ ಏನು ಹೇಳಬಲ್ಲವು',
  },
  'The calculators provide transparent scenarios. GeM determines seller acceptance, buyers award contracts, and only independently reviewed evidence counts as a verified outcome. Bid2Scale is not a government service or an authorised registration agent.': {
    'mr': 'कॅल्क्युलेटर पारदर्शक परिदृश्य देतात. विक्रेता स्वीकृती GeM ठरवते, खरेदीदार करार देतात, आणि केवळ स्वतंत्रपणे तपासलेला पुरावा हा सत्यापित निकाल मोजला जातो. Bid2Scale ही सरकारी सेवा किंवा अधिकृत नोंदणी एजंट नाही.',
    'bn': 'ক্যালকুলেটরগুলি স্বচ্ছ পরিস্থিতি দেয়। বিক্রেতা গ্রহণ GeM নির্ধারণ করে, ক্রেতারা চুক্তি দেয়, এবং কেবল স্বাধীনভাবে পর্যালোচিত প্রমাণই যাচাইকৃত ফলাফল বলে গণ্য। Bid2Scale কোনো সরকারি সেবা বা অনুমোদিত নিবন্ধন এজেন্ট নয়।',
    'pa': 'ਕੈਲਕੁਲੇਟਰ ਪਾਰਦਰਸ਼ੀ ਦ੍ਰਿਸ਼ ਦਿੰਦੇ ਹਨ। ਵਿਕਰੇਤਾ ਸਵੀਕਾਰਤਾ GeM ਤੈਅ ਕਰਦਾ ਹੈ, ਖਰੀਦਦਾਰ ਇਕਰਾਰਨਾਮੇ ਦਿੰਦੇ ਹਨ, ਅਤੇ ਸਿਰਫ਼ ਸੁਤੰਤਰ ਤੌਰ \'ਤੇ ਸਮੀਖਿਆ ਕੀਤਾ ਸਬੂਤ ਹੀ ਪੁਸ਼ਟੀ ਕੀਤਾ ਨਤੀਜਾ ਮੰਨਿਆ ਜਾਂਦਾ ਹੈ। Bid2Scale ਕੋਈ ਸਰਕਾਰੀ ਸੇਵਾ ਜਾਂ ਅਧਿਕਾਰਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਏਜੰਟ ਨਹੀਂ ਹੈ।',
    'gu': 'કેલ્ક્યુલેટર પારદર્શક પરિસ્થિતિઓ આપે છે. વિક્રેતા સ્વીકૃતિ GeM નક્કી કરે છે, ખરીદદારો કોન્ટ્રાક્ટ આપે છે, અને માત્ર સ્વતંત્ર રીતે ચકાસાયેલ પુરાવો જ ચકાસાયેલ પરિણામ ગણાય છે. Bid2Scale સરકારી સેવા અથવા અધિકૃત નોંધણી એજન્ટ નથી.',
    'ta': 'கால்குலேட்டர்கள் வெளிப்படையான சூழல்களை வழங்குகின்றன. விற்பனையாளர் ஏற்பை GeM தீர்மானிக்கிறது, வாங்குபவர்கள் ஒப்பந்தங்களை வழங்குகிறார்கள், மேலும் சுயாதீனமாக மதிப்பாய்வு செய்யப்பட்ட ஆதாரம் மட்டுமே சரிபார்க்கப்பட்ட முடிவாகக் கருதப்படும். Bid2Scale அரசு சேவை அல்லது அங்கீகரிக்கப்பட்ட பதிவு முகவர் அல்ல.',
    'te': 'కాలిక్యులేటర్లు పారదర్శక దృశ్యాలను అందిస్తాయి. విక్రేత అంగీకారాన్ని GeM నిర్ణయిస్తుంది, కొనుగోలుదారులు కాంట్రాక్టులు ఇస్తారు, మరియు స్వతంత్రంగా సమీక్షించిన ఆధారం మాత్రమే ధృవీకరించబడిన ఫలితంగా పరిగణించబడుతుంది. Bid2Scale ప్రభుత్వ సేవ లేదా అధీకృత నమోదు ఏజెంట్ కాదు.',
    'kn': 'ಕ್ಯಾಲ್ಕುಲೇಟರ್‌ಗಳು ಪಾರದರ್ಶಕ ಸನ್ನಿವೇಶಗಳನ್ನು ನೀಡುತ್ತವೆ. ಮಾರಾಟಗಾರ ಸ್ವೀಕಾರವನ್ನು GeM ನಿರ್ಧರಿಸುತ್ತದೆ, ಖರೀದಿದಾರರು ಒಪ್ಪಂದಗಳನ್ನು ನೀಡುತ್ತಾರೆ, ಮತ್ತು ಸ್ವತಂತ್ರವಾಗಿ ಪರಿಶೀಲಿಸಿದ ಪುರಾವೆ ಮಾತ್ರ ಪರಿಶೀಲಿತ ಫಲಿತಾಂಶವಾಗಿ ಪರಿಗಣಿಸಲ್ಪಡುತ್ತದೆ. Bid2Scale ಸರ್ಕಾರಿ ಸೇವೆ ಅಥವಾ ಅಧಿಕೃತ ನೋಂದಣಿ ಏಜೆಂಟ್ ಅಲ್ಲ.',
  },
