  'Policy sources reviewed 9 September 2026. Category benchmark data is published only with a source, sample size, date and methodology.': {
    'mr': 'धोरण स्रोत 9 सप्टेंबर 2026 रोजी तपासले. श्रेणी बेंचमार्क डेटा फक्त स्रोत, नमुना आकार, तारीख आणि पद्धतीसह प्रकाशित केला जातो.',
    'bn': 'নীতি সূত্র ৯ সেপ্টেম্বর ২০২৬ পর্যালোচিত। বিভাগ বেঞ্চমার্ক ডেটা শুধু উৎস, নমুনার আকার, তারিখ ও পদ্ধতির সাথে প্রকাশিত হয়।',
    'pa': 'ਨੀਤੀ ਸਰੋਤ 9 ਸਤੰਬਰ 2026 ਨੂੰ ਸਮੀਖਿਆ ਕੀਤੇ ਗਏ। ਸ਼੍ਰੇਣੀ ਬੈਂਚਮਾਰਕ ਡਾਟਾ ਸਿਰਫ਼ ਸਰੋਤ, ਨਮੂਨਾ ਆਕਾਰ, ਤਾਰੀਖ ਅਤੇ ਵਿਧੀ ਨਾਲ ਪ੍ਰਕਾਸ਼ਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।',
    'gu': 'નીતિ સ્રોતોની 9 સપ્ટેમ્બર 2026ના રોજ સમીક્ષા થઈ. કેટેગરી બેન્ચમાર્ક ડેટા માત્ર સ્રોત, નમૂના કદ, તારીખ અને પદ્ધતિ સાથે પ્રકાશિત થાય છે.',
    'ta': 'கொள்கை ஆதாரங்கள் 9 செப்டம்பர் 2026 அன்று மதிப்பாய்வு செய்யப்பட்டன. வகை பென்ச்மார்க் தரவு ஆதாரம், மாதிரி அளவு, தேதி மற்றும் முறையியலுடன் மட்டுமே வெளியிடப்படுகிறது.',
    'te': 'పాలసీ మూలాలు 9 సెప్టెంబర్ 2026న సమీక్షించబడ్డాయి. కేటగరీ బెంచ్‌మార్క్ డేటా మూలం, నమూనా పరిమాణం, తేదీ మరియు పద్ధతితో మాత్రమే ప్రచురించబడుతుంది.',
    'kn': 'ನೀತಿ ಮೂಲಗಳನ್ನು 9 ಸೆಪ್ಟೆಂಬರ್ 2026 ರಂದು ಪರಿಶೀಲಿಸಲಾಗಿದೆ. ವರ್ಗ ಬೆಂಚ್‌ಮಾರ್ಕ್ ಡೇಟಾವನ್ನು ಮೂಲ, ಮಾದರಿ ಗಾತ್ರ, ದಿನಾಂಕ ಮತ್ತು ವಿಧಾನದೊಂದಿಗೆ ಮಾತ್ರ ಪ್ರಕಟಿಸಲಾಗುತ್ತದೆ.',
