    'ta': 'L1 என்றால் என்ன?',
    'te': 'L1 అంటే ఏమిటి?',
    'kn': 'L1 ಅಂದರೆ ಏನು?',
  },
  'L1 is the lowest evaluated eligible offer. Eligible MSEs within L1 + 15% may get purchase preference by matching L1, subject to the tender and policy. It is not an automatic award.': {
    'mr': 'L1 म्हणजे सर्वात कमी मूल्यांकित पात्र ऑफर. L1 + 15% च्या आतील पात्र MSE ला L1 शी जुळवून घेतल्यास खरेदी प्राधान्य मिळू शकते, टेंडर आणि धोरणाच्या अटींनुसार. हे स्वयंचलित करार नाही.',
    'bn': 'L1 হলো সর্বনিম্ন মূল্যায়িত যোগ্য অফার। L1 + 15%-এর মধ্যে যোগ্য MSE গুলো L1 এর সাথে মিলিয়ে ক্রয় অগ্রাধিকার পেতে পারে, টেন্ডার ও নীতির শর্তে। এটি স্বয়ংক্রিয় পুরস্কার নয়।',
    'pa': 'L1 ਸਭ ਤੋਂ ਘੱਟ ਮੁਲਾਂਕਣ ਕੀਤੀ ਯੋਗ ਪੇਸ਼ਕਸ਼ ਹੈ। L1 + 15% ਦੇ ਅੰਦਰ ਯੋਗ MSE L1 ਨਾਲ ਮਿਲਾ ਕੇ ਖਰੀਦ ਤਰਜੀਹ ਪ੍ਰਾਪਤ ਕਰ ਸਕਦੇ ਹਨ, ਟੈਂਡਰ ਅਤੇ ਨੀਤੀ ਦੇ ਅਧੀਨ। ਇਹ ਆਟੋਮੈਟਿਕ ਇਨਾਮ ਨਹੀਂ ਹੈ।',
    'gu': 'L1 એ સૌથી ઓછું મૂલ્યાંકિત પાત્ર ઓફર છે. L1 + 15% ની અંદરના પાત્ર MSE L1 સાથે મેળ કરીને ખરીદી પ્રાધાન્ય મેળવી શકે છે, ટેન્ડર અને નીતિને આધીન. તે સ્વયંસંચાલિત એવોર્ડ નથી.',
    'ta': 'L1 என்பது மிகக் குறைந்த மதிப்பிடப்பட்ட தகுதியான சலுகை. L1 + 15%-க்குள் உள்ள தகுதியான MSE-கள் L1-ஐப் பொருத்துவதன் மூலம் கொள்முதல் முன்னுரிமையைப் பெறலாம், டெண்டர் மற்றும் கொள்கைக்கு உட்பட்டது. இது தானியங்கி வழங்கல் அல்ல.',
    'te': 'L1 అంటే అత్యల్ప మదింపు చేయబడిన అర్హత గల ఆఫర్. L1 + 15% లోపు అర్హత గల MSEలు L1తో సరిపోల్చడం ద్వారా కొనుగోలు ప్రాధాన్యతను పొందవచ్చు, టెండర్ మరియు పాలసీకి లోబడి. ఇది స్వయంచాలక అవార్డు కాదు.',
    'kn': 'L1 ಎಂದರೆ ಅತ್ಯಂತ ಕಡಿಮೆ ಮೌಲ್ಯಮಾಪನ ಮಾಡಲಾದ ಅರ್ಹ ಆಫರ್. L1 + 15% ಒಳಗಿನ ಅರ್ಹ MSE ಗಳು L1 ಗೆ ಹೊಂದಿಸುವ ಮೂಲಕ ಖರೀದಿ ಆದ್ಯತೆ ಪಡೆಯಬಹುದು, ಟೆಂಡರ್ ಮತ್ತು ನೀತಿಗೆ ಒಳಪಟ್ಟು. ಇದು ಸ್ವಯಂಚಾಲಿತ ಪ್ರದಾನವಲ್ಲ.',
  },
