  'These starting values are editable examples, not category averages. Include zero orders in your downside planning.': {
    'mr': 'ही सुरुवातीची मूल्ये संपादन करण्यायोग्य उदाहरणे आहेत, श्रेणीचे सरासरी नाहीत. तुमच्या डाउनसाइड प्लॅनिंगमध्ये शून्य ऑर्डरचा समावेश करा.',
    'bn': 'এই শুরুর মানগুলি সম্পাদনাযোগ্য উদাহরণ, বিভাগের গড় নয়। আপনার ডাউনসাইড পরিকল্পনায় শূন্য অর্ডার অন্তর্ভুক্ত করুন।',
    'pa': 'ਇਹ ਸ਼ੁਰੂਆਤੀ ਮੁੱਲ ਸੰਪਾਦਨਯੋਗ ਉਦਾਹਰਣ ਹਨ, ਸ਼੍ਰੇਣੀ ਦੇ ਔਸਤ ਨਹੀਂ। ਆਪਣੀ ਡਾਊਨਸਾਈਡ ਯੋਜਨਾ ਵਿੱਚ ਜ਼ੀਰੋ ਆਰਡਰ ਸ਼ਾਮਲ ਕਰੋ।',
    'gu': 'આ શરૂઆતના મૂલ્યો સંપાદનયોગ્ય ઉદાહરણો છે, કેટેગરી સરેરાશ નથી. તમારા ડાઉનસાઇડ પ્લાનિંગમાં શૂન્ય ઓર્ડરનો સમાવેશ કરો.',
    'ta': 'இந்த ஆரம்ப மதிப்புகள் திருத்தக்கூடிய எடுத்துக்காட்டுகள், வகை சராசரிகள் அல்ல. உங்கள் downside திட்டமிடலில் பூஜ்ஜிய ஆர்டர்களைச் சேர்க்கவும்.',
    'te': 'ఈ ప్రారంభ విలువలు సవరించగల ఉదాహరణలు, కేటగరీ సగటులు కాదు. మీ డౌన్‌సైడ్ ప్రణాళికలో సున్నా ఆర్డర్‌లను చేర్చండి.',
    'kn': 'ಈ ಆರಂಭಿಕ ಮೌಲ್ಯಗಳು ಸಂಪಾದಿಸಬಹುದಾದ ಉದಾಹರಣೆಗಳು, ವರ್ಗ ಸರಾಸರಿಗಳಲ್ಲ. ನಿಮ್ಮ ಕುಸಿತ ಯೋಜನೆಯಲ್ಲಿ ಶೂನ್ಯ ಆರ್ಡರ್‌ಗಳನ್ನು ಸೇರಿಸಿ.',
  },
  'Margin = profit ÷ selling price. This is not markup on cost.': {
    'mr': 'मार्जिन = नफा ÷ विक्री किंमत. हे किंमतीवरील मार्कअप नाही.',
    'bn': 'মার্জিন = মুনাফা ÷ বিক্রয় মূল্য। এটি খরচের উপর মার্কআপ নয়।',
    'pa': 'ਮਾਰਜਿਨ = ਲਾਭ ÷ ਵਿਕਰੀ ਕੀਮਤ। ਇਹ ਲਾਗਤ \'ਤੇ ਮਾਰਕਅੱਪ ਨਹੀਂ ਹੈ।',
    'gu': 'માર્જિન = નફો ÷ વેચાણ કિંમત. આ ખર્ચ પર માર્કઅપ નથી.',
    'ta': 'மார்ஜின் = லாபம் ÷ விற்பனை விலை. இது செலவின் மேல் மார்க்அப் அல்ல.',
    'te': 'మార్జిన్ = లాభం ÷ అమ్మకపు ధర. ఇది ఖర్చుపై మార్క్అప్ కాదు.',
    'kn': 'ಮಾರ್ಜಿನ್ = ಲಾಭ ÷ ಮಾರಾಟ ಬೆಲೆ. ಇದು ವೆಚ್ಚದ ಮೇಲಿನ ಮಾರ್ಕಪ್ ಅಲ್ಲ.',
  },
  'Enter a comparable price from a live listing. Use the same unit, specification and tax basis.': {
    'mr': 'लाइव्ह लिस्टिंगमधून तुलनीय किंमत प्रविष्ट करा. समान युनिट, तपशील आणि कर आधार वापरा.',
    'bn': 'লাইভ লিস্টিং থেকে তুলনীয় মূল্য লিখুন। একই ইউনিট, স্পেসিফিকেশন ও কর ভিত্তি ব্যবহার করুন।',
    'pa': 'ਲਾਈਵ ਲਿਸਟਿੰਗ ਤੋਂ ਤੁਲਨਾਤਮਕ ਕੀਮਤ ਦਰਜ ਕਰੋ। ਇੱਕੋ ਇਕਾਈ, ਵਿਸ਼ੇਸ਼ਤਾ ਅਤੇ ਟੈਕਸ ਆਧਾਰ ਵਰਤੋ।',
    'gu': 'લાઇવ લિસ્ટિંગમાંથી તુલનાત્મક કિંમત દાખલ કરો. સમાન યુનિટ, સ્પષ્ટીકરણ અને ટેક્સ આધારનો ઉપયોગ કરો.',
    'ta': 'நேரடி பட்டியலிலிருந்து ஒப்பிடத்தக்க விலையை உள்ளிடுங்கள். அதே யூனிட், விவரக்குறிப்பு மற்றும் வரி அடிப்படையைப் பயன்படுத்துங்கள்.',
    'te': 'లైవ్ లిస్టింగ్ నుండి పోల్చదగిన ధరను నమోదు చేయండి. అదే యూనిట్, స్పెసిఫికేషన్ మరియు పన్ను ఆధారాన్ని ఉపయోగించండి.',
    'kn': 'ಲೈವ್ ಲಿಸ್ಟಿಂಗ್‌ನಿಂದ ಹೋಲಿಸಬಹುದಾದ ಬೆಲೆಯನ್ನು ನಮೂದಿಸಿ. ಅದೇ ಯುನಿಟ್, ವಿಶೇಷಣ ಮತ್ತು ತೆರಿಗೆ ಆಧಾರವನ್ನು ಬಳಸಿ.',
  },
  'Pre-filled from your revenue scenario': {
