    'pa': 'ਤੁਹਾਡੇ ਆਮਦਨ ਦ੍ਰਿਸ਼ ਤੋਂ ਪਹਿਲਾਂ ਤੋਂ ਭਰਿਆ',
    'gu': 'તમારા આવક પરિસ્થિતિમાંથી પૂર્વ-ભરેલું',
    'ta': 'உங்கள் வருமான சூழலிலிருந்து முன்பே நிரப்பப்பட்டது',
    'te': 'మీ ఆదాయ దృశ్యం నుండి ముందుగా నింపబడింది',
    'kn': 'ನಿಮ್ಮ ಆದಾಯ ಸನ್ನಿವೇಶದಿಂದ ಮುಂಚಿತವಾಗಿ ಭರ್ತಿ ಮಾಡಲಾಗಿದೆ',
  },
  'Your estimate for preparation and assistance, not an official registration charge.': {
    'mr': 'तयारी आणि सहाय्यासाठी तुमचा अंदाज, अधिकृत नोंदणी शुल्क नाही.',
    'bn': 'প্রস্তুতি ও সহায়তার জন্য আপনার অনুমান, অফিসিয়াল নিবন্ধন চার্জ নয়।',
    'pa': 'ਤਿਆਰੀ ਅਤੇ ਸਹਾਇਤਾ ਲਈ ਤੁਹਾਡਾ ਅੰਦਾਜ਼ਾ, ਅਧਿਕਾਰਤ ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਖਰਚਾ ਨਹੀਂ।',
    'gu': 'તૈયારી અને સહાય માટે તમારો અંદાજ, સત્તાવાર નોંધણી ચાર્જ નથી.',
    'ta': 'தயாரிப்பு மற்றும் உதவிக்கான உங்கள் மதிப்பீடு, அதிகாரப்பூர்வ பதிவு கட்டணம் அல்ல.',
    'te': 'తయారీ మరియు సహాయం కోసం మీ అంచనా, అధికారిక నమోదు ఛార్జ్ కాదు.',
    'kn': 'ಸಿದ್ಧತೆ ಮತ್ತು ಸಹಾಯಕ್ಕಾಗಿ ನಿಮ್ಮ ಅಂದಾಜು, ಅಧಿಕೃತ ನೋಂದಣಿ ಶುಲ್ಕವಲ್ಲ.',
  },
  'Exclude costs already included in your margin.': {
    'mr': 'तुमच्या मार्जिनमध्ये आधीच समाविष्ट असलेला खर्च वगळा.',
    'bn': 'আপনার মার্জিনে ইতিমধ্যে অন্তর্ভুক্ত খরচ বাদ দিন।',
    'pa': 'ਜੋ ਲਾਗਤ ਤੁਹਾਡੇ ਮਾਰਜਿਨ ਵਿੱਚ ਪਹਿਲਾਂ ਹੀ ਸ਼ਾਮਲ ਹੈ, ਉਸ ਨੂੰ ਬਾਹਰ ਰੱਖੋ।',
    'gu': 'તમારા માર્જિનમાં પહેલેથી સામેલ ખર્ચને બાદ કરો.',
    'ta': 'உங்கள் மார்ஜினில் ஏற்கனவே சேர்க்கப்பட்ட செலவுகளை விலக்கவும்.',
    'te': 'మీ మార్జిన్‌లో ఇప్పటికే చేర్చిన ఖర్చులను మినహాయించండి.',
    'kn': 'ನಿಮ್ಮ ಮಾರ್ಜಿನ್‌ನಲ್ಲಿ ಈಗಾಗಲೇ ಸೇರಿಸಲಾದ ವೆಚ್ಚಗಳನ್ನು ಹೊರತುಪಡಿಸಿ.',
  },
  'MSME classification uses both investment and turnover. Under the thresholds effective 1 April 2025, a micro enterprise can have turnover up to ₹10 crore and investment up to ₹2.5 crore. Your self-label does not decide eligibility.': {
    'mr': 'MSME वर्गीकरण गुंतवणूक आणि उलाढाल दोन्ही वापरते. 1 एप्रिल 2025 पासून लागू मर्यादांनुसार, सूक्ष्म उद्योगाची उलाढाल ₹10 कोटीपर्यंत आणि गुंतवणूक ₹2.5 कोटीपर्यंत असू शकते. तुमचा स्वयं-लेबल पात्रता ठरवत नाही.',
    'bn': 'MSME শ্রেণিবিভাগ বিনিয়োগ ও টার্নওভার দুটিই ব্যবহার করে। ১ এপ্রিল ২০২৫ থেকে কার্যকর সীমার অধীনে, একটি ক্ষুদ্র উদ্যোগের টার্নওভার ₹১০ কোটি পর্যন্ত ও বিনিয়োগ ₹২.৫ কোটি পর্যন্ত হতে পারে। আপনার স্ব-লেবেল যোগ্যতা নির্ধারণ করে না।',
    'pa': 'MSME ਵਰਗੀਕਰਨ ਨਿਵੇਸ਼ ਅਤੇ ਟਰਨਓਵਰ ਦੋਵਾਂ ਦੀ ਵਰਤੋਂ ਕਰਦਾ ਹੈ। 1 ਅਪ੍ਰੈਲ 2025 ਤੋਂ ਲਾਗੂ ਸੀਮਾਵਾਂ ਅਧੀਨ, ਇੱਕ ਸੂਖਮ ਉਦਮ ਦਾ ਟਰਨਓਵਰ ₹10 ਕਰੋੜ ਤੱਕ ਅਤੇ ਨਿਵੇਸ਼ ₹2.5 ਕਰੋੜ ਤੱਕ ਹੋ ਸਕਦਾ ਹੈ। ਤੁਹਾਡਾ ਖੁਦ ਦਾ ਲੇਬਲ ਯੋਗਤਾ ਤੈਅ ਨਹੀਂ ਕਰਦਾ।',
    'gu': 'MSME વર્ગીકરણ રોકાણ અને ટર્નઓવર બંનેનો ઉપયોગ કરે છે. 1 એપ્રિલ 2025થી લાગુ મર્યાદા હેઠળ, સૂક્ષ્મ એન્ટરપ્રાઇઝનું ટર્નઓવર ₹10 કરોડ સુધી અને રોકાણ ₹2.5 કરોડ સુધી હોઈ શકે. તમારું સ્વ-લેબલ પાત્રતા નક્કી કરતું નથી.',
    'ta': 'MSME வகைப்பாடு முதலீடு மற்றும் விற்றுமுதல் இரண்டையும் பயன்படுத்துகிறது. 1 ஏப்ரல் 2025 முதல் நடைமுறையில் உள்ள வரம்புகளின் கீழ், ஒரு மைக்ரோ நிறுவனத்தின் விற்றுமுதல் ₹10 கோடி வரையும் முதலீடு ₹2.5 கோடி வரையும் இருக்கலாம். உங்கள் சுய-லேபிள் தகுதியை தீர்மானிக்காது.',
    'te': 'MSME వర్గీకరణ పెట్టుబడి మరియు టర్నోవర్ రెండింటినీ ఉపయోగిస్తుంది. 1 ఏప్రిల్ 2025 నుండి అమలులో ఉన్న పరిమితుల ప్రకారం, ఒక సూక్ష్మ సంస్థ టర్నోవర్ ₹10 కోట్ల వరకు మరియు పెట్టుబడి ₹2.5 కోట్ల వరకు ఉండవచ్చు. మీ స్వీయ-లేబుల్ అర్హతను నిర్ణయించదు.',
    'kn': 'MSME ವರ್ಗೀಕರಣ ಹೂಡಿಕೆ ಮತ್ತು ವಹಿವಾಟು ಎರಡನ್ನೂ ಬಳಸುತ್ತದೆ. 1 ಏಪ್ರಿಲ್ 2025 ರಿಂದ ಜಾರಿಯಲ್ಲಿರುವ ಮಿತಿಗಳ ಅಡಿಯಲ್ಲಿ, ಒಂದು ಸೂಕ್ಷ್ಮ ಉದ್ಯಮದ ವಹಿವಾಟು ₹10 ಕೋಟಿಯವರೆಗೆ ಮತ್ತು ಹೂಡಿಕೆ ₹2.5 ಕೋಟಿಯವರೆಗೆ ಇರಬಹುದು. ನಿಮ್ಮ ಸ್ವಯಂ-ಲೇಬಲ್ ಅರ್ಹತೆಯನ್ನು ನಿರ್ಧರಿಸುವುದಿಲ್ಲ.',
  },
  'Tender values are buyer demand, not seller earnings. Competition, capacity and delivery area affect your chances. We never infer your likely revenue from national GMV (total value traded).': {
    'mr': 'टेंडर मूल्ये खरेदीदाराची मागणी आहे, विक्रेत्याचे उत्पन्न नाही. स्पर्धा, क्षमता आणि डिलिव्हरी क्षेत्र तुमच्या संधीवर परिणाम करतात. आम्ही राष्ट्रीय GMV (एकूण व्यापार मूल्य) वरून तुमचे संभाव्य उत्पन्न कधीही अनुमानित करत नाही.',
    'bn': 'টেন্ডার মূল্য ক্রেতার চাহিদা, বিক্রেতার আয় নয়। প্রতিযোগিতা, ক্ষমতা ও ডেলিভারি এলাকা আপনার সুযোগে প্রভাব ফেলে। আমরা জাতীয় GMV (মোট লেনদেনের মূল্য) থেকে আপনার সম্ভাব্য আয় কখনো অনুমান করি না।',
    'pa': 'ਟੈਂਡਰ ਮੁੱਲ ਖਰੀਦਦਾਰ ਦੀ ਮੰਗ ਹੈ, ਵਿਕਰੇਤਾ ਦੀ ਆਮਦਨ ਨਹੀਂ। ਮੁਕਾਬਲਾ, ਸਮਰੱਥਾ ਅਤੇ ਡਿਲੀਵਰੀ ਖੇਤਰ ਤੁਹਾਡੇ ਮੌਕਿਆਂ ਨੂੰ ਪ੍ਰਭਾਵਿਤ ਕਰਦੇ ਹਨ। ਅਸੀਂ ਕਦੇ ਵੀ ਰਾਸ਼ਟਰੀ GMV (ਕੁੱਲ ਵਪਾਰ ਮੁੱਲ) ਤੋਂ ਤੁਹਾਡੀ ਸੰਭਾਵਿਤ ਆਮਦਨ ਦਾ ਅਨੁਮਾਨ ਨਹੀਂ ਲਗਾਉਂਦੇ।',
    'gu': 'ટેન્ડર મૂલ્યો ખરીદદારની માંગ છે, વિક્રેતાની કમાણી નથી. હરીફાઈ, ક્ષમતા અને ડિલિવરી વિસ્તાર તમારી તકોને અસર કરે છે. અમે રાષ્ટ્રીય GMV (કુલ વ્યાપાર મૂલ્ય) પરથી તમારી સંભવિત આવકનું અનુમાન કદી લગાવતા નથી.',
    'ta': 'டெண்டர் மதிப்புகள் வாங்குபவரின் தேவை, விற்பனையாளரின் வருமானம் அல்ல. போட்டி, திறன் மற்றும் விநியோக பகுதி உங்கள் வாய்ப்புகளை பாதிக்கும். தேசிய GMV (மொத்த வர்த்தக மதிப்பு) இலிருந்து உங்கள் வருமானத்தை நாங்கள் ஒருபோதும் ஊகிக்க மாட்டோம்.',
    'te': 'టెండర్ విలువలు కొనుగోలుదారు డిమాండ్, విక్రేత ఆదాయం కాదు. పోటీ, సామర్థ్యం మరియు డెలివరీ ప్రాంతం మీ అవకాశాలను ప్రభావితం చేస్తాయి. జాతీయ GMV (మొత్తం వ్యాపార విలువ) నుండి మీ సంభావ్య ఆదాయాన్ని మేము ఎప్పుడూ అంచనా వేయము.',
    'kn': 'ಟೆಂಡರ್ ಮೌಲ್ಯಗಳು ಖರೀದಿದಾರರ ಬೇಡಿಕೆ, ಮಾರಾಟಗಾರರ ಗಳಿಕೆಯಲ್ಲ. ಸ್ಪರ್ಧೆ, ಸಾಮರ್ಥ್ಯ ಮತ್ತು ವಿತರಣಾ ಪ್ರದೇಶ ನಿಮ್ಮ ಅವಕಾಶಗಳನ್ನು ಪ್ರಭಾವಿಸುತ್ತವೆ. ರಾಷ್ಟ್ರೀಯ GMV (ಒಟ್ಟು ವ್ಯಾಪಾರ ಮೌಲ್ಯ) ದಿಂದ ನಿಮ್ಮ ಸಂಭಾವ್ಯ ಆದಾಯವನ್ನು ನಾವು ಎಂದಿಗೂ ಊಹಿಸುವುದಿಲ್ಲ.',
  },
  'The 17.5% starting margin is the median reported in the project brief’s 20-owner survey. It is an interview benchmark, not a GeM market price. Check taxes, financing and order-level fees separately.': {
    'mr': '17.5% प्रारंभिक मार्जिन हे प्रकल्प संक्षिप्ताच्या 20-मालक सर्वेक्षणातील माध्यिका आहे. हे मुलाखतीचे बेंचमार्क आहे, GeM बाजार किंमत नाही. कर, वित्तपुरवठा आणि ऑर्डर-स्तरीय शुल्क वेगळे तपासा.',
    'bn': '১৭.৫% প্রারম্ভিক মার্জিন প্রকল্প সংক্ষিপ্তের ২০-মালিক সমীক্ষার মধ্যক। এটি একটি সাক্ষাৎকার বেঞ্চমার্ক, GeM বাজার মূল্য নয়। কর, অর্থায়ন ও অর্ডার-স্তরের ফি আলাদাভাবে পরীক্ষা করুন।',
    'pa': '17.5% ਸ਼ੁਰੂਆਤੀ ਮਾਰਜਿਨ ਪ੍ਰੋਜੈਕਟ ਸੰਖੇਪ ਦੇ 20-ਮਾਲਕ ਸਰਵੇ ਵਿੱਚ ਦਰਜ ਮੱਧਮਾਨ ਹੈ। ਇਹ ਇੱਕ ਇੰਟਰਵਿਊ ਬੈਂਚਮਾਰਕ ਹੈ, GeM ਬਾਜ਼ਾਰ ਕੀਮਤ ਨਹੀਂ। ਟੈਕਸ, ਵਿੱਤ ਅਤੇ ਆਰਡਰ-ਪੱਧਰ ਦੀਆਂ ਫੀਸਾਂ ਵੱਖਰੇ ਤੌਰ \'ਤੇ ਜਾਂਚੋ।',
    'gu': '17.5% શરૂઆતનું માર્જિન પ્રોજેક્ટ સંક્ષિપ્તના 20-માલિક સર્વેમાં નોંધાયેલ મધ્યક છે. તે ઇન્ટરવ્યૂ બેન્ચમાર્ક છે, GeM બજાર કિંમત નથી. ટેક્સ, ફાઇનાન્સિંગ અને ઓર્ડર-સ્તરની ફી અલગથી ચકાસો.',
    'ta': '17.5% ஆரம்ப மார்ஜின் திட்டச் சுருக்கத்தின் 20-உரிமையாளர் கணக்கெடுப்பில் பதிவான நடுநிலை மதிப்பு. இது ஒரு நேர்காணல் பென்ச்மார்க், GeM சந்தை விலை அல்ல. வரிகள், நிதியுதவி மற்றும் ஆர்டர்-நிலை கட்டணங்களை தனித்தனியாக சரிபார்க்கவும்.',
    'te': '17.5% ప్రారంభ మార్జిన్ ప్రాజెక్ట్ బ్రీఫ్ యొక్క 20-యజమాని సర్వేలో నివేదించబడిన మధ్యస్థం. ఇది ఇంటర్వ్యూ బెంచ్‌మార్క్, GeM మార్కెట్ ధర కాదు. పన్నులు, ఫైనాన్సింగ్ మరియు ఆర్డర్-స్థాయి ఫీజులను వేరుగా తనిఖీ చేయండి.',
    'kn': '17.5% ಆರಂಭಿಕ ಮಾರ್ಜಿನ್ ಪ್ರಾಜೆಕ್ಟ್ ಸಾರಾಂಶದ 20-ಮಾಲೀಕರ ಸಮೀಕ್ಷೆಯಲ್ಲಿ ವರದಿಯಾದ ಮಧ್ಯಮ ಮೌಲ್ಯ. ಇದು ಸಂದರ್ಶನ ಬೆಂಚ್‌ಮಾರ್ಕ್, GeM ಮಾರುಕಟ್ಟೆ ಬೆಲೆ ಅಲ್ಲ. ತೆರಿಗೆಗಳು, ಹಣಕಾಸು ಮತ್ತು ಆರ್ಡರ್-ಮಟ್ಟದ ಶುಲ್ಕಗಳನ್ನು ಪ್ರತ್ಯೇಕವಾಗಿ ಪರಿಶೀಲಿಸಿ.',
  },
  'All time estimates are your assumptions until validated through Pune SME journeys. Payback uses contribution after GeM fees, not gross revenue. Working capital, taxes and payment delays can change the outcome.': {
    'mr': 'पुणे SME प्रवासाद्वारे सत्यापित होईपर्यंत सर्व वेळेचे अंदाज तुमची गृहीतके आहेत. परतफेड GeM शुल्कानंतरचे योगदान वापरते, सकल उत्पन्न नाही. कार्यशील भांडवल, कर आणि पेमेंट विलंब निकाल बदलू शकतात.',
    'bn': 'পুনে SME যাত্রার মাধ্যমে যাচাই না হওয়া পর্যন্ত সব সময়ের অনুমান আপনার ধারণা। ফেরত GeM ফি-এর পরের অবদান ব্যবহার করে, গ্রস আয় নয়। কার্যকরী মূলধন, কর ও পেমেন্ট বিলম্ব ফলাফল বদলাতে পারে।',
    'pa': 'ਪੂਨੇ SME ਸਫ਼ਰ ਰਾਹੀਂ ਪੁਸ਼ਟੀ ਹੋਣ ਤੱਕ ਸਾਰੇ ਸਮੇਂ ਦੇ ਅੰਦਾਜ਼ੇ ਤੁਹਾਡੀਆਂ ਧਾਰਨਾਵਾਂ ਹਨ। ਵਾਪਸੀ GeM ਫੀਸਾਂ ਤੋਂ ਬਾਅਦ ਦੇ ਯੋਗਦਾਨ ਦੀ ਵਰਤੋਂ ਕਰਦੀ ਹੈ, ਕੁੱਲ ਆਮਦਨ ਨਹੀਂ। ਕਾਰਜਸ਼ੀਲ ਪੂੰਜੀ, ਟੈਕਸ ਅਤੇ ਭੁਗਤਾਨ ਦੇਰੀ ਨਤੀਜਾ ਬਦਲ ਸਕਦੇ ਹਨ।',
    'gu': 'પુણે SME યાત્રા દ્વારા ચકાસાય ત્યાં સુધી બધા સમયના અંદાજ તમારી ધારણાઓ છે. વળતર GeM ફી પછીના ફાળાનો ઉપયોગ કરે છે, કુલ આવક નહીં. કાર્યકારી મૂડી, ટેક્સ અને ચુકવણી વિલંબ પરિણામ બદલી શકે છે.',
    'ta': 'புனே SME பயணங்கள் மூலம் சரிபார்க்கப்படும் வரை அனைத்து நேர மதிப்பீடுகளும் உங்கள் கருதுகோள்கள். மீட்பு GeM கட்டணங்களுக்குப் பிறகான பங்களிப்பைப் பயன்படுத்துகிறது, மொத்த வருமானம் அல்ல. நடைமுறை மூலதனம், வரிகள் மற்றும் கட்டண தாமதங்கள் முடிவை மாற்றலாம்.',
    'te': 'పూణే SME ప్రయాణాల ద్వారా ధృవీకరించే వరకు అన్ని సమయ అంచనాలు మీ ఊహలే. తిరిగి రావడం GeM ఫీజుల తర్వాత సహకారాన్ని ఉపయోగిస్తుంది, గ్రాస్ ఆదాయం కాదు. వర్కింగ్ కేపిటల్, పన్నులు మరియు చెల్లింపు ఆలస్యాలు ఫలితాన్ని మార్చగలవు.',
    'kn': 'ಪುಣೆ SME ಪ್ರಯಾಣಗಳ ಮೂಲಕ ಪರಿಶೀಲಿಸುವವರೆಗೆ ಎಲ್ಲಾ ಸಮಯದ ಅಂದಾಜುಗಳು ನಿಮ್ಮ ಊಹೆಗಳಾಗಿವೆ. ಮರುಪಾವತಿ GeM ಶುಲ್ಕಗಳ ನಂತರದ ಕೊಡುಗೆಯನ್ನು ಬಳಸುತ್ತದೆ, ಒಟ್ಟು ಆದಾಯವಲ್ಲ. ಕಾರ್ಯನಿರತ ಬಂಡವಾಳ, ತೆರಿಗೆಗಳು ಮತ್ತು ಪಾವತಿ ವಿಳಂಬಗಳು ಫಲಿತಾಂಶವನ್ನು ಬದಲಾಯಿಸಬಹುದು.',
  },
  'Procurement evidence': {
