  'No verified sample has been published for this category and city. Average order value, active buyer count and procurement frequency are unavailable. Your calculator still works as a planning scenario.': {
    'mr': 'या श्रेणी आणि शहरासाठी सत्यापित नमुना प्रकाशित केलेला नाही. सरासरी ऑर्डर मूल्य, सक्रिय खरेदीदार संख्या आणि खरेदी वारंवारता उपलब्ध नाही. तुमचे कॅल्क्युलेटर तरीही प्लॅनिंग परिदृश्य म्हणून काम करते.',
    'bn': 'এই বিভাগ ও শহরের জন্য কোনো যাচাইকৃত নমুনা প্রকাশিত হয়নি। গড় অর্ডার মূল্য, সক্রিয় ক্রেতা সংখ্যা ও সংগ্রহের ফ্রিকোয়েন্সি অনুপলব্ধ। আপনার ক্যালকুলেটর তবুও একটি পরিকল্পনা পরিস্থিতি হিসেবে কাজ করে।',
    'pa': 'ਇਸ ਸ਼੍ਰੇਣੀ ਅਤੇ ਸ਼ਹਿਰ ਲਈ ਕੋਈ ਪੁਸ਼ਟੀ ਕੀਤਾ ਨਮੂਨਾ ਪ੍ਰਕਾਸ਼ਿਤ ਨਹੀਂ ਹੋਇਆ। ਔਸਤ ਆਰਡਰ ਮੁੱਲ, ਸਰਗਰਮ ਖਰੀਦਦਾਰ ਗਿਣਤੀ ਅਤੇ ਖਰੀਦ ਦੀ ਬਾਰੰਬਾਰਤਾ ਉਪਲਬਧ ਨਹੀਂ। ਤੁਹਾਡਾ ਕੈਲਕੁਲੇਟਰ ਫਿਰ ਵੀ ਯੋਜਨਾ ਦ੍ਰਿਸ਼ ਵਜੋਂ ਕੰਮ ਕਰਦਾ ਹੈ।',
    'gu': 'આ કેટેગરી અને શહેર માટે કોઈ ચકાસાયેલ સેમ્પલ પ્રકાશિત થયું નથી. સરેરાશ ઓર્ડર મૂલ્ય, સક્રિય ખરીદદાર સંખ્યા અને પ્રોક્યોરમેન્ટ આવર્તન અનુપલબ્ધ છે. તમારું કેલ્ક્યુલેટર છતાં પ્લાનિંગ પરિસ્થિતિ તરીકે કામ કરે છે.',
    'ta': 'இந்த வகை மற்றும் நகருக்கு சரிபார்க்கப்பட்ட மாதிரி வெளியிடப்படவில்லை. சராசரி ஆர்டர் மதிப்பு, செயலில் உள்ள வாங்குபவர் எண்ணிக்கை மற்றும் கொள்முதல் அதிர்வெண் கிடைக்கவில்லை. உங்கள் கால்குலேட்டர் இன்னும் திட்டமிடல் சூழலாக செயல்படுகிறது.',
    'te': 'ఈ కేటగరీ మరియు నగరానికి ధృవీకరించబడిన నమూనా ప్రచురించబడలేదు. సగటు ఆర్డర్ విలువ, యాక్టివ్ కొనుగోలుదారు సంఖ్య మరియు ప్రొక్యూర్‌మెంట్ ఫ్రీక్వెన్సీ అందుబాటులో లేవు. మీ కాలిక్యులేటర్ ఇప్పటికీ ప్రణాళిక దృశ్యంగా పనిచేస్తుంది.',
    'kn': 'ಈ ವರ್ಗ ಮತ್ತು ನಗರಕ್ಕೆ ಯಾವುದೇ ಪರಿಶೀಲಿತ ಮಾದರಿಯನ್ನು ಪ್ರಕಟಿಸಲಾಗಿಲ್ಲ. ಸರಾಸರಿ ಆರ್ಡರ್ ಮೌಲ್ಯ, ಸಕ್ರಿಯ ಖರೀದಿದಾರರ ಸಂಖ್ಯೆ ಮತ್ತು ಖರೀದಿ ಆವರ್ತನ ಲಭ್ಯವಿಲ್ಲ. ನಿಮ್ಮ ಕ್ಯಾಲ್ಕುಲೇಟರ್ ಇನ್ನೂ ಯೋಜನಾ ಸನ್ನಿವೇಶವಾಗಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ.',
  },
  'The cautious count must not exceed the optimistic count.': {
