    'te': 'జాగ్రత్తగా ఉన్న సంఖ్య ఆశావాద సంఖ్యను మించకూడదు.',
    'kn': 'ಎಚ್ಚರಿಕೆಯ ಸಂಖ್ಯೆ ಆಶಾವಾದಿ ಸಂಖ್ಯೆಯನ್ನು ಮೀರಬಾರದು.',
  },
  'Result saved. Scroll down to see your next step.': {
    'mr': 'निकाल सेव्ह झाला. तुमचे पुढील पाऊल पाहण्यासाठी खाली स्क्रोल करा.',
    'bn': 'ফলাফল সংরক্ষিত। পরবর্তী পদক্ষেপ দেখতে নিচে স্ক্রল করুন।',
    'pa': 'ਨਤੀਜਾ ਸੇਵ ਹੋਇਆ। ਆਪਣਾ ਅਗਲਾ ਕਦਮ ਦੇਖਣ ਲਈ ਹੇਠਾਂ ਸਕ੍ਰੋਲ ਕਰੋ।',
    'gu': 'પરિણામ સેવ થયું. તમારું આગલું પગલું જોવા નીચે સ્ક્રોલ કરો.',
    'ta': 'முடிவு சேமிக்கப்பட்டது. உங்கள் அடுத்த படியைப் பார்க்க கீழே ஸ்க்ரோல் செய்யுங்கள்.',
