  'Fee model: ₹0 on orders up to ₹10 lakh; 0.3% of total order value above ₹10 lakh, capped at ₹3 lakh per order. Excludes tax on fees. Confirm the current policy before bidding.': {
    'mr': 'शुल्क मॉडेल: ₹10 लाखांपर्यंतच्या ऑर्डरवर ₹0; ₹10 लाखांपेक्षा जास्त एकूण ऑर्डर मूल्यावर 0.3%, प्रति ऑर्डर ₹3 लाखांची मर्यादा. शुल्कावरील कर वगळलेला. बिड करण्यापूर्वी सध्याचे धोरण तपासा.',
    'bn': 'ফি মডেল: ₹১০ লাখ পর্যন্ত অর্ডারে ₹০; ₹১০ লাখের বেশি মোট অর্ডার মূল্যে ০.৩%, প্রতি অর্ডারে ₹৩ লাখ পর্যন্ত সীমিত। ফি-এর উপর কর অন্তর্ভুক্ত নয়। বিড করার আগে বর্তমান নীতি নিশ্চিত করুন।',
    'pa': 'ਫੀਸ ਮਾਡਲ: ₹10 ਲੱਖ ਤੱਕ ਦੇ ਆਰਡਰ \'ਤੇ ₹0; ₹10 ਲੱਖ ਤੋਂ ਵੱਧ ਕੁੱਲ ਆਰਡਰ ਮੁੱਲ \'ਤੇ 0.3%, ਪ੍ਰਤੀ ਆਰਡਰ ₹3 ਲੱਖ ਤੱਕ ਸੀਮਿਤ। ਫੀਸਾਂ \'ਤੇ ਟੈਕਸ ਸ਼ਾਮਲ ਨਹੀਂ। ਬਿੱਡ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਮੌਜੂਦਾ ਨੀਤੀ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।',
    'gu': 'ફી મોડેલ: ₹10 લાખ સુધીના ઓર્ડર પર ₹0; ₹10 લાખથી વધુ કુલ ઓર્ડર મૂલ્ય પર 0.3%, પ્રતિ ઓર્ડર ₹3 લાખ સુધી મર્યાદિત. ફી પર ટેક્સ સામેલ નથી. બિડ કરતા પહેલા વર્તમાન નીતિની પુષ્ટિ કરો.',
    'ta': 'கட்டண மாதிரி: ₹10 லட்சம் வரையிலான ஆர்டர்களுக்கு ₹0; ₹10 லட்சத்திற்கு மேலான மொத்த ஆர்டர் மதிப்பில் 0.3%, ஒரு ஆர்டருக்கு ₹3 லட்சம் வரை வரம்பு. கட்டணங்களுக்கான வரி தவிர்க்கப்பட்டுள்ளது. ஏலம் விடுவதற்கு முன் தற்போதைய கொள்கையை உறுதிசெய்யுங்கள்.',
    'te': 'ఫీజు మోడల్: ₹10 లక్షల వరకు ఆర్డర్‌లపై ₹0; ₹10 లక్షలకు మించిన మొత్తం ఆర్డర్ విలువపై 0.3%, ఒక్కో ఆర్డర్‌కు ₹3 లక్షలకు పరిమితం. ఫీజులపై పన్ను చేర్చబడలేదు. బిడ్ చేయడానికి ముందు ప్రస్తుత పాలసీని నిర్ధారించుకోండి.',
    'kn': 'ಶುಲ್ಕ ಮಾದರಿ: ₹10 ಲಕ್ಷದವರೆಗಿನ ಆರ್ಡರ್‌ಗಳ ಮೇಲೆ ₹0; ₹10 ಲಕ್ಷಕ್ಕಿಂತ ಹೆಚ್ಚಿನ ಒಟ್ಟು ಆರ್ಡರ್ ಮೌಲ್ಯದ ಮೇಲೆ 0.3%, ಪ್ರತಿ ಆರ್ಡರ್‌ಗೆ ₹3 ಲಕ್ಷಕ್ಕೆ ಸೀಮಿತ. ಶುಲ್ಕಗಳ ಮೇಲಿನ ತೆರಿಗೆ ಹೊರತುಪಡಿಸಲಾಗಿದೆ. ಬಿಡ್ ಮಾಡುವ ಮೊದಲು ಪ್ರಸ್ತುತ ನೀತಿಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  },
  'PIB · 21 Sep 2024; effective 9 Aug 2024': {
    'mr': 'PIB · 21 सप्टेंबर 2024; लागू 9 ऑगस्ट 2024',
    'bn': 'PIB · ২১ সেপ্টেম্বর ২০২৪; কার্যকর ৯ আগস্ট ২০২৪',
    'pa': 'PIB · 21 ਸਤੰਬਰ 2024; ਲਾਗੂ 9 ਅਗਸਤ 2024',
    'gu': 'PIB · 21 સપ્ટેમ્બર 2024; લાગુ 9 ઓગસ્ટ 2024',
    'ta': 'PIB · 21 செப் 2024; நடைமுறை 9 ஆக 2024',
    'te': 'PIB · 21 సెప్టెంబర్ 2024; అమలు 9 ఆగస్టు 2024',
    'kn': 'PIB · 21 ಸೆಪ್ಟೆಂಬರ್ 2024; ಜಾರಿ 9 ಆಗಸ್ಟ್ 2024',
  },
  'Yes — ready to explore registration': {
    'mr': 'हो — नोंदणी एक्सप्लोर करण्यास तयार',
    'bn': 'হ্যাঁ — নিবন্ধন অন্বেষণে প্রস্তুত',
    'pa': 'ਹਾਂ — ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਦੀ ਪੜਚੋਲ ਕਰਨ ਲਈ ਤਿਆਰ',
    'gu': 'હા — નોંધણી શોધવા તૈયાર',
    'ta': 'ஆம் — பதிவை ஆராய தயார்',
    'te': 'అవును — నమోదును అన్వేషించడానికి సిద్ధం',
    'kn': 'ಹೌದು — ನೋಂದಣಿಯನ್ನು ಅನ್ವೇಷಿಸಲು ಸಿದ್ಧ',
  },
  'Government sales aren’t your priority right now': {
    'mr': 'सध्या सरकारी विक्री तुमची प्राथमिकता नाही',
    'bn': 'সরকারি বিক্রয় এখন আপনার অগ্রাধিকার নয়',
    'pa': 'ਸਰਕਾਰੀ ਵਿਕਰੀ ਹੁਣ ਤੁਹਾਡੀ ਤਰਜੀਹ ਨਹੀਂ',
    'gu': 'સરકારી વેચાણ હાલ તમારી પ્રાધાન્યતા નથી',
    'ta': 'அரசு விற்பனை இப்போது உங்கள் முன்னுரிமை அல்ல',
    'te': 'ప్రభుత్వ అమ్మకాలు ఇప్పుడు మీ ప్రాధాన్యత కాదు',
    'kn': 'ಸರ್ಕಾರಿ ಮಾರಾಟ ಈಗ ನಿಮ್ಮ ಆದ್ಯತೆಯಲ್ಲ',
  },
  'Partial — a few details to resolve': {
    'mr': 'अंशतः — काही तपशील पूर्ण करायचे आहेत',
    'bn': 'আংশিক — কিছু বিবরণ সমাধান করা বাকি',
    'pa': 'ਅੰਸ਼ਕ — ਕੁਝ ਵੇਰਵੇ ਹੱਲ ਕਰਨੇ ਹਨ',
    'gu': 'આંશિક — કેટલીક વિગતો ઉકેલવાની બાકી',
    'ta': 'பகுதி — சில விவரங்கள் தீர்க்கப்பட வேண்டும்',
    'te': 'పాక్షికం — కొన్ని వివరాలు పరిష్కరించాలి',
    'kn': 'ಭಾಗಶಃ — ಕೆಲವು ವಿವರಗಳನ್ನು ಪರಿಹರಿಸಬೇಕಿದೆ',
  },
  'Prepare the relevant PAN and authorised-person identity details. Confirm the accepted route on GeM.': {
    'mr': 'संबंधित PAN आणि अधिकृत व्यक्तीचे ओळख तपशील तयार करा. GeM वरील स्वीकृत मार्ग तपासा.',
    'bn': 'সংশ্লিষ্ট PAN ও অনুমোদিত ব্যক্তির পরিচয় বিবরণ প্রস্তুত করুন। GeM-এ গৃহীত পথ নিশ্চিত করুন।',
    'pa': 'ਸੰਬੰਧਿਤ PAN ਅਤੇ ਅਧਿਕਾਰਤ ਵਿਅਕਤੀ ਦੇ ਪਛਾਣ ਵੇਰਵੇ ਤਿਆਰ ਕਰੋ। GeM \'ਤੇ ਸਵੀਕਾਰਿਤ ਰਾਹ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।',
    'gu': 'સંબંધિત PAN અને અધિકૃત વ્યક્તિની ઓળખ વિગતો તૈયાર કરો. GeM પર સ્વીકૃત માર્ગની પુષ્ટિ કરો.',
    'ta': 'தொடர்புடைய PAN மற்றும் அங்கீகரிக்கப்பட்ட நபர் அடையாள விவரங்களைத் தயார் செய்யுங்கள். GeM-இல் ஏற்கப்பட்ட வழியை உறுதிசெய்யுங்கள்.',
    'te': 'సంబంధిత PAN మరియు అధీకృత వ్యక్తి గుర్తింపు వివరాలను సిద్ధం చేయండి. GeMలో అనుమతించబడిన మార్గాన్ని నిర్ధారించుకోండి.',
    'kn': 'ಸಂಬಂಧಿತ PAN ಮತ್ತು ಅಧಿಕೃತ ವ್ಯಕ್ತಿಯ ಗುರುತಿನ ವಿವರಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಿ. GeM ನಲ್ಲಿ ಅಂಗೀಕೃತ ಮಾರ್ಗವನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  },
  'Prepare business bank details and confirm account requirements with your bank.': {
    'mr': 'व्यवसाय बँक तपशील तयार करा आणि तुमच्या बँकेकडून खाते आवश्यकता तपासा.',
    'bn': 'ব্যবসার ব্যাঙ্ক বিবরণ প্রস্তুত করুন এবং আপনার ব্যাঙ্কের সাথে অ্যাকাউন্টের প্রয়োজনীয়তা নিশ্চিত করুন।',
    'pa': 'ਕਾਰੋਬਾਰੀ ਬੈਂਕ ਵੇਰਵੇ ਤਿਆਰ ਕਰੋ ਅਤੇ ਆਪਣੇ ਬੈਂਕ ਨਾਲ ਖਾਤਾ ਲੋੜਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।',
    'gu': 'બિઝનેસ બેંક વિગતો તૈયાર કરો અને તમારી બેંક સાથે ખાતાની જરૂરિયાતોની પુષ્ટિ કરો.',
    'ta': 'வணிக வங்கி விவரங்களைத் தயார் செய்து உங்கள் வங்கியுடன் கணக்குத் தேவைகளை உறுதிசெய்யுங்கள்.',
    'te': 'వ్యాపార బ్యాంక్ వివరాలను సిద్ధం చేసి మీ బ్యాంక్‌తో ఖాతా అవసరాలను నిర్ధారించుకోండి.',
    'kn': 'ವ್ಯಾಪಾರ ಬ್ಯಾಂಕ್ ವಿವರಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಿ ಮತ್ತು ನಿಮ್ಮ ಬ್ಯಾಂಕ್‌ನೊಂದಿಗೆ ಖಾತೆ ಅಗತ್ಯಗಳನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  },
  'Confirm GST applicability or exemption with your CA and the official portal before proceeding.': {
    'mr': 'पुढे जाण्यापूर्वी तुमच्या CA आणि अधिकृत पोर्टलसह GST लागू आहे किंवा सूट आहे याची पुष्टी करा.',
    'bn': 'এগিয়ে যাওয়ার আগে আপনার CA ও অফিসিয়াল পোর্টালের সাথে GST প্রযোজ্যতা বা ছাড় নিশ্চিত করুন।',
    'pa': 'ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ CA ਅਤੇ ਅਧਿਕਾਰਤ ਪੋਰਟਲ ਨਾਲ GST ਲਾਗੂ ਹੋਣ ਜਾਂ ਛੋਟ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।',
    'gu': 'આગળ વધતા પહેલા તમારા CA અને સત્તાવાર પોર્ટલ સાથે GST લાગુ પડે છે કે મુક્તિ છે તેની પુષ્ટિ કરો.',
    'ta': 'தொடர்வதற்கு முன் உங்கள் CA மற்றும் அதிகாரப்பூர்வ போர்ட்டலுடன் GST பொருந்துமா அல்லது விலக்கு உள்ளதா என உறுதிசெய்யுங்கள்.',
    'te': 'కొనసాగించే ముందు మీ CA మరియు అధికారిక పోర్టల్‌తో GST వర్తింపు లేదా మినహాయింపును నిర్ధారించుకోండి.',
    'kn': 'ಮುಂದುವರಿಯುವ ಮೊದಲು ನಿಮ್ಮ CA ಮತ್ತು ಅಧಿಕೃತ ಪೋರ್ಟಲ್‌ನೊಂದಿಗೆ GST ಅನ್ವಯ ಅಥವಾ ವಿನಾಯಿತಿಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  },
  'Find the closest permitted category and its catalogue requirements on GeM.': {
    'mr': 'GeM वर सर्वात जवळची अनुमत श्रेणी आणि तिच्या कॅटलॉग आवश्यकता शोधा.',
    'bn': 'GeM-এ সবচেয়ে কাছের অনুমোদিত বিভাগ ও তার ক্যাটালগ প্রয়োজনীয়তা খুঁজুন।',
    'pa': 'GeM \'ਤੇ ਸਭ ਤੋਂ ਨੇੜਲੀ ਮਨਜ਼ੂਰਸ਼ੁਦਾ ਸ਼੍ਰੇਣੀ ਅਤੇ ਇਸਦੀ ਕੈਟਾਲਾਗ ਲੋੜਾਂ ਲੱਭੋ।',
    'gu': 'GeM પર સૌથી નજીકની મંજૂર કેટેગરી અને તેની કેટલોગ જરૂરિયાતો શોધો.',
    'ta': 'GeM-இல் மிக நெருக்கமான அனுமதிக்கப்பட்ட வகையையும் அதன் கேட்டலாக் தேவைகளையும் கண்டறியுங்கள்.',
    'te': 'GeMలో దగ్గరగా ఉన్న అనుమతించబడిన కేటగరీ మరియు దాని కేటలాగ్ అవసరాలను కనుగొనండి.',
    'kn': 'GeM ನಲ್ಲಿ ಹತ್ತಿರದ ಅನುಮತಿಸಲಾದ ವರ್ಗ ಮತ್ತು ಅದರ ಕ್ಯಾಟಲಾಗ್ ಅಗತ್ಯಗಳನ್ನು ಕಂಡುಕೊಳ್ಳಿ.',
  },
  'This differs from your selected classification. Both investment and turnover limits must be satisfied.': {
    'mr': 'हे तुमच्या निवडलेल्या वर्गीकरणापेक्षा वेगळे आहे. गुंतवणूक आणि उलाढाल दोन्ही मर्यादा पूर्ण करणे आवश्यक आहे.',
    'bn': 'এটি আপনার নির্বাচিত শ্রেণিবিভাগ থেকে ভিন্ন। বিনিয়োগ ও টার্নওভার দুটি সীমাই পূরণ করতে হবে।',
    'pa': 'ਇਹ ਤੁਹਾਡੇ ਚੁਣੇ ਵਰਗੀਕਰਨ ਤੋਂ ਵੱਖਰਾ ਹੈ। ਨਿਵੇਸ਼ ਅਤੇ ਟਰਨਓਵਰ ਦੋਵਾਂ ਸੀਮਾਵਾਂ ਨੂੰ ਪੂਰਾ ਕਰਨਾ ਜ਼ਰੂਰੀ ਹੈ।',
    'gu': 'આ તમારા પસંદ કરેલા વર્ગીકરણથી અલગ છે. રોકાણ અને ટર્નઓવર બંને મર્યાદા સંતોષવી જરૂરી છે.',
    'ta': 'இது நீங்கள் தேர்ந்தெடுத்த வகைப்பாட்டிலிருந்து வேறுபட்டது. முதலீடு மற்றும் விற்றுமுதல் இரு வரம்புகளும் பூர்த்தி செய்யப்பட வேண்டும்.',
    'te': 'ఇది మీరు ఎంచుకున్న వర్గీకరణ నుండి భిన్నంగా ఉంది. పెట్టుబడి మరియు టర్నోవర్ రెండు పరిమితులు తీర్చాలి.',
    'kn': 'ಇದು ನಿಮ್ಮ ಆಯ್ಕೆಮಾಡಿದ ವರ್ಗೀಕರಣಕ್ಕಿಂತ ಭಿನ್ನವಾಗಿದೆ. ಹೂಡಿಕೆ ಮತ್ತು ವಹಿವಾಟು ಎರಡು ಮಿತಿಗಳನ್ನೂ ಪೂರೈಸಬೇಕು.',
  },
  'Udyam is worth exploring for MSE benefits; missing Udyam alone does not make you ineligible for GeM.': {
    'mr': 'MSE लाभांसाठी Udyam एक्सप्लोर करणे योग्य आहे; फक्त Udyam नसणे तुम्हाला GeM साठी अपात्र बनवत नाही.',
    'bn': 'MSE সুবিধার জন্য Udyam অন্বেষণ করা ভালো; শুধু Udyam না থাকা আপনাকে GeM-এর অযোগ্য করে না।',
    'pa': 'MSE ਲਾਭਾਂ ਲਈ Udyam ਦੀ ਪੜਚੋਲ ਕਰਨਾ ਲਾਭਦਾਇਕ ਹੈ; ਸਿਰਫ਼ Udyam ਨਾ ਹੋਣਾ ਤੁਹਾਨੂੰ GeM ਲਈ ਅਯੋਗ ਨਹੀਂ ਬਣਾਉਂਦਾ।',
    'gu': 'MSE લાભો માટે Udyam શોધવું યોગ્ય છે; ફક્ત Udyam ન હોવાથી તમે GeM માટે અપાત્ર બનતા નથી.',
    'ta': 'MSE பலன்களுக்கு Udyam-ஐ ஆராய்வது நல்லது; Udyam இல்லாதது மட்டும் உங்களை GeM-க்கு தகுதியற்றவராக ஆக்காது.',
    'te': 'MSE ప్రయోజనాల కోసం Udyam అన్వేషించడం విలువైనది; Udyam లేకపోవడం మాత్రమే మిమ్మల్ని GeM కోసం అనర్హులను చేయదు.',
    'kn': 'MSE ಪ್ರಯೋಜನಗಳಿಗಾಗಿ Udyam ಅನ್ವೇಷಿಸುವುದು ಯೋಗ್ಯ; ಕೇವಲ Udyam ಇಲ್ಲದಿರುವುದು ನಿಮ್ಮನ್ನು GeM ಗೆ ಅನರ್ಹಗೊಳಿಸುವುದಿಲ್ಲ.',
  },
  'This is a preliminary readiness assessment. The portal, category and buyer requirements decide actual acceptance. Time to resolve gaps varies; no validated Pune timing sample is available yet.': {
    'mr': 'हे प्राथमिक तयारी मूल्यांकन आहे. पोर्टल, श्रेणी आणि खरेदीदाराच्या आवश्यकता प्रत्यक्ष स्वीकृती ठरवतात. त्रुटी सोडवण्याची वेळ बदलते; अद्याप सत्यापित पुणे वेळ नमुना उपलब्ध नाही.',
    'bn': 'এটি একটি প্রাথমিক প্রস্তুতি মূল্যায়ন। পোর্টাল, বিভাগ ও ক্রেতার প্রয়োজনীয়তা প্রকৃত গ্রহণযোগ্যতা নির্ধারণ করে। ফাঁক সমাধানের সময় ভিন্ন হয়; এখনো কোনো যাচাইকৃত পুনে সময় নমুনা নেই।',
    'pa': 'ਇਹ ਇੱਕ ਸ਼ੁਰੂਆਤੀ ਤਿਆਰੀ ਮੁਲਾਂਕਣ ਹੈ। ਪੋਰਟਲ, ਸ਼੍ਰੇਣੀ ਅਤੇ ਖਰੀਦਦਾਰ ਲੋੜਾਂ ਅਸਲ ਸਵੀਕਾਰਤਾ ਤੈਅ ਕਰਦੀਆਂ ਹਨ। ਖਾਮੀਆਂ ਹੱਲ ਕਰਨ ਦਾ ਸਮਾਂ ਵੱਖ-ਵੱਖ ਹੁੰਦਾ ਹੈ; ਅਜੇ ਕੋਈ ਪੁਸ਼ਟੀ ਕੀਤਾ ਪੂਨੇ ਸਮਾਂ ਨਮੂਨਾ ਉਪਲਬਧ ਨਹੀਂ।',
    'gu': 'આ પ્રાથમિક તૈયારી મૂલ્યાંકન છે. પોર્ટલ, કેટેગરી અને ખરીદદારની જરૂરિયાતો વાસ્તવિક સ્વીકૃતિ નક્કી કરે છે. ખામી ઉકેલવાનો સમય બદલાય છે; હજુ કોઈ ચકાસાયેલ પુણે સમય સેમ્પલ ઉપલબ્ધ નથી.',
    'ta': 'இது ஒரு ஆரம்ப தயார்நிலை மதிப்பீடு. போர்ட்டல், வகை மற்றும் வாங்குபவர் தேவைகள் உண்மையான ஏற்பை தீர்மானிக்கும். இடைவெளிகளைத் தீர்க்க நேரம் மாறுபடும்; இன்னும் சரிபார்க்கப்பட்ட புனே நேர மாதிரி இல்லை.',
    'te': 'ఇది ప్రాథమిక సన్నద్ధత మదింపు. పోర్టల్, కేటగరీ మరియు కొనుగోలుదారు అవసరాలు వాస్తవ అంగీకారాన్ని నిర్ణయిస్తాయి. లోపాలను పరిష్కరించే సమయం మారుతుంది; ఇంకా ధృవీకరించిన పూణే సమయ నమూనా అందుబాటులో లేదు.',
    'kn': 'ಇದು ಪ್ರಾಥಮಿಕ ಸನ್ನದ್ಧತಾ ಮೌಲ್ಯಮಾಪನ. ಪೋರ್ಟಲ್, ವರ್ಗ ಮತ್ತು ಖರೀದಿದಾರರ ಅಗತ್ಯಗಳು ನಿಜವಾದ ಸ್ವೀಕಾರವನ್ನು ನಿರ್ಧರಿಸುತ್ತವೆ. ಕೊರತೆಗಳನ್ನು ಪರಿಹರಿಸಲು ಸಮಯ ಬದಲಾಗುತ್ತದೆ; ಇನ್ನೂ ಪರಿಶೀಲಿತ ಪುಣೆ ಸಮಯ ಮಾದರಿ ಲಭ್ಯವಿಲ್ಲ.',
  },
