    'ta': '"தொடங்குங்கள்" மற்றும் மொழி திரைகளை மீண்டும் பார்க்கவும். உங்கள் சேமிக்கப்பட்ட கருவிகள் மற்றும் முன்னேற்றம் பாதிக்கப்படாது.',
