  'If you’re assisting someone else, the authorised person must complete GeM registration.': {
    'mr': 'तुम्ही कोणाला मदत करत असाल, तर अधिकृत व्यक्तीनेच GeM नोंदणी पूर्ण करावी लागेल.',
    'bn': 'আপনি অন্য কাউকে সাহায্য করলে, অনুমোদিত ব্যক্তিকেই GeM নিবন্ধন সম্পন্ন করতে হবে।',
