  'GeM may ask that person to verify identity with Aadhaar or personal PAN details. Don’t enter those details here.': {
    'mr': 'GeM त्या व्यक्तीस आधार किंवा वैयक्तिक PAN ने ओळख सत्यापित करण्यास सांगू शकते. ती माहिती इथे देऊ नका.',
    'bn': 'GeM সেই ব্যক্তিকে আধার বা ব্যক্তিগত PAN দিয়ে পরিচয় যাচাই করতে বলতে পারে। এখানে সেই তথ্য দেবেন না।',
    'pa': 'GeM ਉਸ ਵਿਅਕਤੀ ਨੂੰ ਆਧਾਰ ਜਾਂ ਨਿੱਜੀ PAN ਨਾਲ ਪਛਾਣ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਕਹਿ ਸਕਦਾ ਹੈ। ਇਹ ਵੇਰਵੇ ਇੱਥੇ ਨਾ ਦਿਓ।',
    'gu': 'GeM તે વ્યક્તિને આધાર અથવા વ્યક્તિગત PAN વડે ઓળખ ચકાસવા કહી શકે છે. તે વિગતો અહીં ન આપો.',
    'ta': 'அந்த நபரிடம் ஆதார் அல்லது தனிப்பட்ட PAN மூலம் அடையாளத்தை உறுதிப்படுத்தச் சொல்லக்கூடும். அந்த விவரங்களை இங்கே கொடுக்க வேண்டாம்.',
    'te': 'ఆధార్ లేదా వ్యక్తిగత PAN వివరాలతో గుర్తింపును నిర్ధారించమని GeM ఆ వ్యక్తిని అడగవచ్చు. ఆ వివరాలను ఇక్కడ ఇవ్వకండి.',
    'kn': 'ಆಧಾರ್ ಅಥವಾ ವ್ಯಕ್ತಿಗತ PAN ಮೂಲಕ ಗುರುತನ್ನು ಪರಿಶೀಲಿಸಲು GeM ಆ ವ್ಯಕ್ತಿಯನ್ನು ಕೇಳಬಹುದು. ಆ ವಿವರಗಳನ್ನು ಇಲ್ಲಿ ನೀಡಬೇಡಿ.',
  },
