  'We’ll use your answers to tailor a readiness guide.': {
    'mr': 'तुमच्या उत्तरांवरून आम्ही एक तयारी गाइड बनवू.',
    'bn': 'আপনার উত্তর দিয়ে আমরা একটি প্রস্তুতি গাইড তৈরি করব।',
    'pa': 'ਅਸੀਂ ਤੁਹਾਡੇ ਜਵਾਬਾਂ ਨਾਲ ਇੱਕ ਤਿਆਰੀ ਗਾਈਡ ਬਣਾਵਾਂਗੇ।',
    'gu': 'અમે તમારા જવાબોથી એક તૈયારી ગાઇડ બનાવીશું.',
    'ta': 'உங்கள் பதில்களைப் பயன்படுத்தி ஒரு தயார்நிலை வழிகாட்டியை உருவாக்குவோம்.',
    'te': 'మీ సమాధానాలతో ఒక సన్నద్ధత గైడ్‌ను తయారు చేస్తాము.',
    'kn': 'ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು ಬಳಸಿ ಸಿದ್ಧತಾ ಗೈಡ್ ರೂಪಿಸುತ್ತೇವೆ.',
  },
  'No PAN, Aadhaar, ITR files, or GeM passwords are collected here.': {
    'mr': 'येथे PAN, आधार, ITR फाइल्स किंवा GeM पासवर्ड घेतले जात नाहीत.',
    'bn': 'এখানে PAN, আধার, ITR ফাইল বা GeM পাসওয়ার্ড সংগ্রহ করা হয় না।',
    'pa': 'ਇੱਥੇ PAN, ਆਧਾਰ, ITR ਫਾਈਲਾਂ ਜਾਂ GeM ਪਾਸਵਰਡ ਇਕੱਠੇ ਨਹੀਂ ਕੀਤੇ ਜਾਂਦੇ।',
    'gu': 'અહીં PAN, આધાર, ITR ફાઇલો અથવા GeM પાસવર્ડ એકત્રિત કરવામાં આવતા નથી.',
    'ta': 'இங்கே PAN, ஆதார், ITR கோப்புகள் அல்லது GeM கடவுச்சொற்கள் சேகரிக்கப்படுவதில்லை.',
    'te': 'ఇక్కడ PAN, ఆధార్, ITR ఫైళ్లు లేదా GeM పాస్‌వర్డ్‌లు సేకరించబడవు.',
    'kn': 'ಇಲ್ಲಿ PAN, ಆಧಾರ್, ITR ಫೈಲುಗಳು ಅಥವಾ GeM ಪಾಸ್‌ವರ್ಡ್‌ಗಳನ್ನು ಸಂಗ್ರಹಿಸಲಾಗುವುದಿಲ್ಲ.',
  },
  'This prototype keeps your answers only while this page is open. No real OTP is sent.': {
    'mr': 'हे प्रोटोटाइप तुमची उत्तरे फक्त हे पान उघडे असताना ठेवते. कोणताही खरा OTP पाठवला जात नाही.',
    'bn': 'এই প্রোটোটাইপ আপনার উত্তর কেবল এই পেজ খোলা থাকা পর্যন্ত রাখে। কোনো আসল OTP পাঠানো হয় না।',
    'pa': 'ਇਹ ਪ੍ਰੋਟੋਟਾਈਪ ਤੁਹਾਡੇ ਜਵਾਬ ਸਿਰਫ਼ ਇਸ ਪੰਨੇ ਦੇ ਖੁੱਲ੍ਹੇ ਹੋਣ ਤੱਕ ਰੱਖਦਾ ਹੈ। ਕੋਈ ਅਸਲੀ OTP ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ।',
    'gu': 'આ પ્રોટોટાઇપ તમારા જવાબો માત્ર આ પેજ ખુલ્લું હોય ત્યાં સુધી રાખે છે. કોઈ સાચો OTP મોકલવામાં આવતો નથી.',
    'ta': 'இந்த முன்மாதிரி இந்தப் பக்கம் திறந்திருக்கும் வரை மட்டும் உங்கள் பதில்களை வைத்திருக்கும். உண்மையான OTP அனுப்பப்படாது.',
    'te': 'ఈ ప్రోటోటైప్ ఈ పేజీ తెరిచి ఉన్నంత వరకు మాత్రమే మీ సమాధానాలను ఉంచుతుంది. ఎలాంటి నిజమైన OTP పంపబడదు.',
    'kn': 'ಈ ಪ್ರೋಟೋಟೈಪ್ ಈ ಪುಟ ತೆರೆದಿರುವಷ್ಟು ಕಾಲ ಮಾತ್ರ ನಿಮ್ಮ ಉತ್ತರಗಳನ್ನು ಇಡುತ್ತದೆ. ಯಾವುದೇ ನಿಜವಾದ OTP ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.',
  },
  'You’ll enter registration details yourself on the official GeM portal.': {
    'mr': 'तुम्ही स्वतः अधिकृत GeM पोर्टलवर नोंदणी माहिती भराल.',
    'bn': 'আপনি নিজে সরকারি GeM পোর্টালে নিবন্ধনের তথ্য দেবেন।',
    'pa': 'ਤੁਸੀਂ ਖੁਦ ਅਧਿਕਾਰਤ GeM ਪੋਰਟਲ \'ਤੇ ਰਜਿਸਟਰੇਸ਼ਨ ਵੇਰਵੇ ਦਰਜ ਕਰੋਗੇ।',
    'gu': 'તમે જાતે સત્તાવાર GeM પોર્ટલ પર નોંધણી વિગતો દાખલ કરશો.',
    'ta': 'நீங்களே அதிகாரப்பூர்வ GeM போர்ட்டலில் பதிவு விவரங்களை உள்ளிடுவீர்கள்.',
    'te': 'మీరే అధికారిక GeM పోర్టల్‌లో నమోదు వివరాలను నమోదు చేస్తారు.',
    'kn': 'ನೀವೇ ಅಧಿಕೃತ GeM ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ನೋಂದಣಿ ವಿವರಗಳನ್ನು ನಮೂದಿಸುತ್ತೀರಿ.',
  },
  'I understand this is a preparation guide.': {
    'mr': 'मला समजते की ही एक तयारी गाइड आहे.',
    'bn': 'আমি বুঝি এটি একটি প্রস্তুতি গাইড।',
    'pa': 'ਮੈਂ ਸਮਝਦਾ/ਸਮਝਦੀ ਹਾਂ ਕਿ ਇਹ ਇੱਕ ਤਿਆਰੀ ਗਾਈਡ ਹੈ।',
    'gu': 'હું સમજું છું કે આ એક તૈયારી ગાઇડ છે.',
    'ta': 'இது ஒரு தயார்நிலை வழிகாட்டி என்பதை நான் புரிந்துகொள்கிறேன்.',
    'te': 'ఇది ఒక సన్నద్ధత గైడ్ అని నేను అర్థం చేసుకున్నాను.',
    'kn': 'ಇದು ಒಂದು ಸಿದ್ಧತಾ ಗೈಡ್ ಎಂದು ನಾನು ಅರ್ಥಮಾಡಿಕೊಂಡಿದ್ದೇನೆ.',
  },
  'GET READY · 5 OF 5': {
    'mr': 'तयार व्हा · 5 पैकी 5',
