  'Which business records do you have ready?': {
    'mr': 'तुमच्याकडे कोणते व्यवसाय दस्तावेज तयार आहेत?',
    'bn': 'আপনার কাছে কোন ব্যবসার রেকর্ড প্রস্তুত আছে?',
    'pa': 'ਤੁਹਾਡੇ ਕੋਲ ਕਿਹੜੇ ਕਾਰੋਬਾਰੀ ਰਿਕਾਰਡ ਤਿਆਰ ਹਨ?',
    'gu': 'તમારી પાસે કયા બિઝનેસ રેકોર્ડ તૈયાર છે?',
    'ta': 'உங்களிடம் எந்த வணிக ஆவணங்கள் தயாராக உள்ளன?',
    'te': 'మీ వద్ద ఏ వ్యాపార రికార్డులు సిద్ధంగా ఉన్నాయి?',
    'kn': 'ನಿಮ್ಮಲ್ಲಿ ಯಾವ ವ್ಯಾಪಾರ ದಾಖಲೆಗಳು ಸಿದ್ಧವಾಗಿವೆ?',
  },
  'Select all that apply. Requirements can vary by business type and activity.\n\nWe’ll only save your readiness answer—not document numbers or files.': {
    'mr': 'लागू असणारे सर्व निवडा. गरजा व्यवसाय प्रकार आणि क्रियेनुसार बदलू शकतात.\n\nआम्ही फक्त तुमचे तयारी उत्तर जपू—दस्तावेज क्रमांक किंवा फाइल्स नाही.',
    'bn': 'প্রযোজ্য সবগুলো বেছে নিন। প্রয়োজনীয়তা ব্যবসার ধরন ও কাজের ভিত্তিতে ভিন্ন হতে পারে।\n\nআমরা কেবল আপনার প্রস্তুতির উত্তর সংরক্ষণ করব—ডকুমেন্ট নম্বর বা ফাইল নয়।',
    'pa': 'ਜੋ ਲਾਗੂ ਹੁੰਦਾ ਹੈ ਸਭ ਚੁਣੋ। ਲੋੜਾਂ ਕਾਰੋਬਾਰ ਦੀ ਕਿਸਮ ਅਤੇ ਗਤੀਵਿਧੀ ਅਨੁਸਾਰ ਬਦਲ ਸਕਦੀਆਂ ਹਨ।\n\nਅਸੀਂ ਸਿਰਫ਼ ਤੁਹਾਡਾ ਤਿਆਰੀ ਜਵਾਬ ਸੰਭਾਲਾਂਗੇ—ਦਸਤਾਵੇਜ਼ ਨੰਬਰ ਜਾਂ ਫਾਈਲਾਂ ਨਹੀਂ।',
    'gu': 'લાગુ પડતું બધું પસંદ કરો. જરૂરિયાતો બિઝનેસના પ્રકાર અને પ્રવૃત્તિ પ્રમાણે બદલાઈ શકે છે.\n\nઅમે માત્ર તમારો તૈયારીનો જવાબ સાચવીશું—દસ્તાવેજ નંબર અથવા ફાઇલો નહીં.',
    'ta': 'பொருந்தும் அனைத்தையும் தேர்ந்தெடுங்கள். தேவைகள் தொழில் வகை மற்றும் செயல்பாட்டைப் பொறுத்து மாறுபடும்.\n\nநாங்கள் உங்கள் தயார்நிலை பதிலை மட்டுமே சேமிப்போம்—ஆவண எண்கள் அல்லது கோப்புகள் அல்ல.',
    'te': 'వర్తించే అన్నింటినీ ఎంచుకోండి. అవసరాలు వ్యాపార రకం మరియు కార్యకలాపాన్ని బట్టి మారవచ్చు.\n\nమేము మీ సన్నద్ధత సమాధానాన్ని మాత్రమే సేవ్ చేస్తాము—డాక్యుమెంట్ నంబర్లు లేదా ఫైళ్లు కాదు.',
    'kn': 'ಅನ್ವಯವಾಗುವ ಎಲ್ಲವನ್ನೂ ಆಯ್ಕೆಮಾಡಿ. ಅವಶ್ಯಕತೆಗಳು ವ್ಯಾಪಾರ ಪ್ರಕಾರ ಮತ್ತು ಚಟುವಟಿಕೆಯ ಪ್ರಕಾರ ಬದಲಾಗಬಹುದು.\n\nನಾವು ನಿಮ್ಮ ಸಿದ್ಧತಾ ಉತ್ತರವನ್ನು ಮಾತ್ರ ಉಳಿಸುತ್ತೇವೆ—ದಾಖಲೆ ಸಂಖ್ಯೆಗಳು ಅಥವಾ ಫೈಲುಗಳನ್ನಲ್ಲ.',
  },
