  'You’ll enter any required details yourself on the official GeM portal.': {
    'mr': 'आवश्यक असलेली माहिती तुम्ही स्वतः अधिकृत GeM पोर्टलवर भराल.',
    'bn': 'প্রয়োজনীয় তথ্য আপনি নিজে সরকারি GeM পোর্টালে দেবেন।',
