  'We only need a readiness answer—not the PAN number.': {
    'mr': 'आम्हाला फक्त तयारीचे उत्तर हवे—PAN क्रमांक नाही.',
    'bn': 'আমাদের কেবল প্রস্তুতির উত্তর প্রয়োজন—PAN নম্বর নয়।',
