  'This is a sample opportunity for preview. Confirm eligibility, specifications, and closing dates on the official GeM portal.': {
    'mr': 'हे पूर्वावलोकनासाठी एक नमुना संधी आहे. पात्रता, तपशील आणि अंतिम तारखा अधिकृत GeM पोर्टलवर तपासा.',
    'bn': 'এটি প্রিভিউয়ের জন্য একটি নমুনা সুযোগ। যোগ্যতা, বিবরণ এবং সমাপ্তির তারিখ সরকারি GeM পোর্টালে যাচাই করুন।',
    'pa': 'ਇਹ ਪ੍ਰੀਵਿਊ ਲਈ ਇੱਕ ਨਮੂਨਾ ਮੌਕਾ ਹੈ। ਯੋਗਤਾ, ਵੇਰਵੇ ਅਤੇ ਅੰਤਿਮ ਤਾਰੀਖਾਂ ਅਧਿਕਾਰਤ GeM ਪੋਰਟਲ \'ਤੇ ਵੇਖੋ।',
    'gu': 'આ પ્રિવ્યુ માટે એક નમૂનાની તક છે. પાત્રતા, વિગતો અને અંતિમ તારીખો સત્તાવાર GeM પોર્ટલ પર ચકાસો.',
    'ta': 'இது முன்னோட்டத்திற்கான ஒரு மாதிரி வாய்ப்பு. தகுதி, விவரக்குறிப்புகள் மற்றும் இறுதி தேதிகளை அதிகாரப்பூர்வ GeM போர்ட்டலில் உறுதிசெய்யுங்கள்.',
    'te': 'ఇది ప్రివ్యూ కోసం ఒక నమూనా అవకాశం. అర్హత, వివరణలు మరియు ముగింపు తేదీలను అధికారిక GeM పోర్టల్‌లో నిర్ధారించుకోండి.',
    'kn': 'ಇದು ಮುನ್ನೋಟಕ್ಕಾಗಿ ಒಂದು ನಮೂನೆ ಅವಕಾಶ. ಅರ್ಹತೆ, ವಿವರಗಳು ಮತ್ತು ಮುಕ್ತಾಯ ದಿನಾಂಕಗಳನ್ನು ಅಧಿಕೃತ GeM ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
