    'bn': 'বিড করার আগে একটি সহজ হিসাব করুন: ক্রয় খরচ, ডেলিভারি, কর, ফি এবং পেমেন্টের আগের সময় অন্তর্ভুক্त করুন।',
    'pa': 'ਬੋਲੀ ਲਗਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਸਧਾਰਨ ਅੰਦਾਜ਼ਾ ਲਗਾਓ: ਖਰੀਦ ਖਰਚਾ, ਡਿਲਿਵਰੀ, ਟੈਕਸ, ਫੀਸ ਅਤੇ ਭੁਗਤਾਨ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਸਮਾਂ ਸ਼ਾਮਲ ਕਰੋ।',
    'gu': 'બિડ કરતા પહેલા એક સરળ અંદાજ લગાવો: ખરીદી ખર્ચ, ડિલિવરી, ટેક્સ, ફી અને ચુકવણી પહેલાનો સમય શામેલ કરો.',
    'ta': 'ஏலம் விடுவதற்கு முன் ஒரு எளிய மதிப்பீட்டைப் பயன்படுத்துங்கள்: வாங்கும் செலவு, டெலிவரி, வரிகள், கட்டணங்கள் மற்றும் பணம் செலுத்தும் முன் நேரத்தை சேர்க்கவும்.',
    'te': 'బిడ్ చేయడానికి ముందు ఒక సాధారణ అంచనాను ఉపయోగించండి: కొనుగోలు ఖర్చు, డెలివరీ, పన్నులు, ఫీజులు మరియు చెల్లింపుకు ముందు సమయాన్ని చేర్చండి.',
    'kn': 'ಬಿಡ್ ಮಾಡುವ ಮೊದಲು ಸರಳ ಅಂದಾಜನ್ನು ಬಳಸಿ: ಖರೀದಿ ವೆಚ್ಚ, ವಿತರಣೆ, ತೆರಿಗೆಗಳು, ಶುಲ್ಕಗಳು ಮತ್ತು ಪಾವತಿಗೂ ಮೊದಲಿನ ಸಮಯವನ್ನು ಸೇರಿಸಿ.',
