    'pa': 'ਪੁੱਛ ਕੇ ਵੇਖੋ: "ਇਸ ਬੋਲੀ ਲਈ ਅਰਜ਼ੀ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ ਮੈਨੂੰ ਕਿਹੜੇ ਦਸਤਾਵੇਜ਼ ਤਿਆਰ ਰੱਖਣੇ ਚਾਹੀਦੇ ਹਨ?"',
    'gu': 'પૂછીને જુઓ: "આ બિડ માટે અરજી કરતા પહેલા મારે કયા દસ્તાવેજો તૈયાર રાખવા જોઈએ?"',
    'ta': 'கேட்டு பாருங்கள்: "இந்த ஏலத்திற்கு விண்ணப்பிக்கும் முன் நான் எந்த ஆவணங்களைத் தயார் செய்ய வேண்டும்?"',
    'te': 'అడిగి చూడండి: "ఈ బిడ్ కోసం దరఖాస్తు చేయడానికి ముందు నేను ఏ పత్రాలను సిద్ధం చేసుకోవాలి?"',
    'kn': 'ಕೇಳಿ ನೋಡಿ: "ಈ ಬಿಡ್‌ಗೆ ಅರ್ಜಿ ಸಲ್ಲಿಸುವ ಮೊದಲು ನಾನು ಯಾವ ದಾಖಲೆಗಳನ್ನು ಸಿದ್ಧಪಡಿಸಬೇಕು?"',
