  'What’s your business’s annual turnover (latest FY)?': {
    'mr': 'तुमच्या व्यवसायाचा नवीनतम आर्थिक वर्षाचा वार्षिक उलाढाल किती आहे?',
    'bn': 'আপনার ব্যবসার সর্বশেষ অর্থবছরের বার্ষিক টার্নওভার কত?',
    'gu': 'તમારા વ્યવસાયનું નવીનતમ નાણાકીય વર્ષનું વાર્ષિક ટર્નઓવર શું છે?',
    'pa': 'ਤੁਹਾਡੇ ਕਾਰੋਬਾਰ ਦਾ ਨਵੀਨਤਮ ਵਿੱਤੀ ਸਾਲ ਦਾ ਸਾਲਾਨਾ ਟਰਨਓਵਰ ਕੀ ਹੈ?',
