    'te': 'మీ వ్యాపారం యొక్క తాజా ఆర్థిక సంవత్సరపు వార్షిక టర్నోవర్ ఎంత?',
    'kn': 'ನಿಮ್ಮ ವ್ಯಾಪಾರದ ಇತ್ತೀಚಿನ ಹಣಕಾಸು ವರ್ಷದ ವಾರ್ಷಿಕ ವಹಿವಾಟು ಎಷ್ಟು?',
  },
  'This helps explain turnover criteria you may see in GeM bids. Use FY 2025–26; a range is enough.': {
    'mr': 'यामुळे GeM बोलींमध्ये दिसणाऱ्या उलाढाल निकषांचे स्पष्टीकरण मिळते. आर्थिक वर्ष 2025-26 वापरा; श्रेणी पुरेशी आहे.',
    'bn': 'এটি GeM বিডে দেখা টার্নওভার শর্ত বুঝতে সাহায্য করে। অর্থবছর 2025–26 ব্যবহার করুন; একটি পরিসীমা যথেষ্ট।',
    'gu': 'આ GeM બિડમાં દેખાતા ટર્નઓવર માપદંડ સમજવામાં મદદ કરે છે. નાણાકીય વર્ષ 2025–26 વાપરો; એક શ્રેણી પૂરતી છે.',
    'pa': 'ਇਹ GeM ਬੋਲੀਆਂ ਵਿੱਚ ਦਿਖਣ ਵਾਲੀਆਂ ਟਰਨਓਵਰ ਸ਼ਰਤਾਂ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਵਿੱਤੀ ਸਾਲ 2025–26 ਵਰਤੋ; ਇੱਕ ਸੀਮਾ ਕਾਫ਼ੀ ਹੈ।',
    'ta': 'இது GeM ஏலங்களில் காணக்கூடிய விற்றுமுதல் நிபந்தனைகளை விளக்க உதவும். நிதியாண்டு 2025–26 ஐப் பயன்படுத்தவும்; ஒரு வரம்பு போதுமானது.',
    'te': 'ఇది GeM బిడ్‌లలో కనిపించే టర్నోవర్ ప్రమాణాలను వివరించడంలో సహాయపడుతుంది. ఆర్థిక సంవత్సరం 2025–26 ఉపయోగించండి; ఒక పరిధి సరిపోతుంది.',
    'kn': 'ಇದು GeM ಬಿಡ್‌ಗಳಲ್ಲಿ ಕಾಣಿಸುವ ವಹಿವಾಟು ಮಾನದಂಡಗಳನ್ನು ವಿವರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಹಣಕಾಸು ವರ್ಷ 2025–26 ಬಳಸಿ; ಒಂದು ಶ್ರೇಣಿ ಸಾಕು.',
  },
  'No exact figure or documents needed. This is preparation guidance—not an eligibility decision.': {
    'mr': 'नेमकी आकडेवारी किंवा कागदपत्रांची आवश्यकता नाही. हे तयारीचे मार्गदर्शन आहे—पात्रतेचा निर्णय नाही.',
    'bn': 'সঠিক পরিসংখ্যান বা কাগজপত্রের প্রয়োজন নেই। এটি প্রস্তুতির নির্দেশনা—যোগ্যতার সিদ্ধান্ত নয়।',
    'gu': 'ચોક્કસ આંકડો અથવા દસ્તાવેજોની જરૂર નથી. આ તૈયારી માર્ગદર્શન છે—પાત્રતાનો નિર્ણય નથી.',
    'pa': 'ਸਟੀਕ ਅੰਕੜੇ ਜਾਂ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਲੋੜ ਨਹੀਂ। ਇਹ ਤਿਆਰੀ ਮਾਰਗਦਰਸ਼ਨ ਹੈ—ਯੋਗਤਾ ਦਾ ਫੈਸਲਾ ਨਹੀਂ।',
    'ta': 'சரியான எண் அல்லது ஆவணங்கள் தேவையில்லை. இது தயாரிப்பு வழிகாட்டுதல்—தகுதி முடிவு அல்ல.',
    'te': 'ఖచ్చితమైన సంఖ్య లేదా పత్రాలు అవసరం లేదు. ఇది తయారీ మార్గదర్శకత్వం—అర్హత నిర్ణయం కాదు.',
    'kn': 'ನಿಖರ ಅಂಕಿ ಅಥವಾ ದಾಖಲೆಗಳ ಅಗತ್ಯವಿಲ್ಲ. ಇದು ತಯಾರಿ ಮಾರ್ಗದರ್ಶನ—ಅರ್ಹತೆಯ ನಿರ್ಧಾರವಲ್ಲ.',
  },
  'And the two years before that, roughly?': {
    'mr': 'आणि त्याआधीची दोन वर्षे, अंदाजे?',
    'bn': 'এবং তার আগের দুই বছর, আনুমানিক?',
    'gu': 'અને તેના પહેલાના બે વર્ષ, અંદાજે?',
    'pa': 'ਅਤੇ ਉਸ ਤੋਂ ਪਹਿਲਾਂ ਦੇ ਦੋ ਸਾਲ, ਲਗਭਗ?',
    'ta': 'அதற்கு முந்தைய இரண்டு ஆண்டுகள், தோராயமாக?',
    'te': 'దానికి ముందు రెండు సంవత్సరాలు, సుమారుగా?',
    'kn': 'ಮತ್ತು ಅದಕ್ಕೂ ಮುಂಚಿನ ಎರಡು ವರ್ಷಗಳು, ಸುಮಾರಾಗಿ?',
  },
  'Some GeM bids assess turnover across three financial years. Estimates help explain those requirements; choose “Same as latest FY” if unsure.': {
    'mr': 'काही GeM बोली तीन आर्थिक वर्षांच्या उलाढालीचे मूल्यांकन करतात. अंदाज या निकषांचे स्पष्टीकरण देण्यास मदत करतात; अनिश्चित असल्यास “नवीनतम आर्थिक वर्षाप्रमाणे” निवडा.',
    'bn': 'কিছু GeM বিড তিনটি অর্থবছরের টার্নওভার মূল্যায়ন করে। অনুমান এই শর্তগুলি বুঝতে সাহায্য করে; অনিশ্চিত হলে “সর্বশেষ অর্থবছরের মতো” বেছে নিন।',
    'gu': 'કેટલીક GeM બિડ ત્રણ નાણાકીય વર્ષોના ટર્નઓવરનું મૂલ્યાંકન કરે છે. અંદાજ આ માપદંડ સમજવામાં મદદ કરે છે; અનિશ્ચિત હો તો “નવીનતમ નાણાકીય વર્ષ જેવું” પસંદ કરો.',
    'pa': 'ਕੁਝ GeM ਬੋਲੀਆਂ ਤਿੰਨ ਵਿੱਤੀ ਸਾਲਾਂ ਦੇ ਟਰਨਓਵਰ ਦਾ ਮੁਲਾਂਕਣ ਕਰਦੀਆਂ ਹਨ। ਅਨੁਮਾਨ ਇਹ ਸ਼ਰਤਾਂ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਨ; ਅਨਿਸ਼ਚਿਤ ਹੋ ਤਾਂ “ਨਵੀਨਤਮ ਵਿੱਤੀ ਸਾਲ ਵਾਂਗ” ਚੁਣੋ।',
    'ta': 'சில GeM ஏலங்கள் மூன்று நிதியாண்டுகளின் விற்றுமுதலை மதிப்பிடுகின்றன. மதிப்பீடுகள் இந்த நிபந்தனைகளை விளக்க உதவும்; உறுதியில்லை என்றால் “சமீபத்திய நிதியாண்டு போல” தேர்ந்தெடுக்கவும்.',
    'te': 'కొన్ని GeM బిడ్‌లు మూడు ఆర్థిక సంవత్సరాల టర్నోవర్‌ను అంచనా వేస్తాయి. అంచనాలు ఈ ప్రమాణాలను వివరించడంలో సహాయపడతాయి; అనిశ్చితంగా ఉంటే “తాజా ఆర్థిక సంవత్సరం లాగే” ఎంచుకోండి.',
    'kn': 'ಕೆಲವು GeM ಬಿಡ್‌ಗಳು ಮೂರು ಹಣಕಾಸು ವರ್ಷಗಳ ವಹಿವಾಟನ್ನು ನಿರ್ಣಯಿಸುತ್ತವೆ. ಅಂದಾಜುಗಳು ಈ ಮಾನದಂಡಗಳನ್ನು ವಿವರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತವೆ; ಖಚಿತವಿಲ್ಲದಿದ್ದರೆ “ಇತ್ತೀಚಿನ ಹಣಕಾಸು ವರ್ಷದಂತೆ” ಆಯ್ಕೆಮಾಡಿ.',
  },
  'Ranges are enough. This is preparation guidance, not an eligibility decision.': {
    'mr': 'श्रेणी पुरेशी आहे. हे तयारीचे मार्गदर्शन आहे, पात्रतेचा निर्णय नाही.',
    'bn': 'পরিসীমা যথেষ্ট। এটি প্রস্তুতির নির্দেশনা, যোগ্যতার সিদ্ধান্ত নয়।',
    'gu': 'શ્રેણીઓ પૂરતી છે. આ તૈયારી માર્ગદર્શન છે, પાત્રતાનો નિર્ણય નથી.',
    'pa': 'ਸੀਮਾਵਾਂ ਕਾਫ਼ੀ ਹਨ। ਇਹ ਤਿਆਰੀ ਮਾਰਗਦਰਸ਼ਨ ਹੈ, ਯੋਗਤਾ ਦਾ ਫੈਸਲਾ ਨਹੀਂ।',
    'ta': 'வரம்புகள் போதுமானவை. இது தயாரிப்பு வழிகாட்டுதல், தகுதி முடிவு அல்ல.',
    'te': 'పరిధులు సరిపోతాయి. ఇది తయారీ మార్గదర్శకత్వం, అర్హత నిర్ణయం కాదు.',
    'kn': 'ಶ್ರೇಣಿಗಳು ಸಾಕು. ಇದು ತಯಾರಿ ಮಾರ್ಗದರ್ಶನ, ಅರ್ಹತೆಯ ನಿರ್ಧಾರವಲ್ಲ.',
  },
  'Same as latest FY': {
    'mr': 'नवीनतम आर्थिक वर्षाप्रमाणे',
    'bn': 'সর্বশেষ অর্থবছরের মতো',
    'gu': 'નવીનતમ નાણાકીય વર્ષ જેવું',
    'pa': 'ਨਵੀਨਤਮ ਵਿੱਤੀ ਸਾਲ ਵਾਂਗ',
    'ta': 'சமீபத்திய நிதியாண்டு போல',
    'te': 'తాజా ఆర్థిక సంవత్సరం లాగే',
    'kn': 'ಇತ್ತೀಚಿನ ಹಣಕಾಸು ವರ್ಷದಂತೆ',
  },
  'Choose a range': {
    'mr': 'श्रेणी निवडा',
    'bn': 'একটি পরিসীমা বেছে নিন',
    'gu': 'શ્રેણી પસંદ કરો',
    'pa': 'ਸੀਮਾ ਚੁਣੋ',
    'ta': 'ஒரு வரம்பைத் தேர்ந்தெடுக்கவும்',
    'te': 'ఒక పరిధిని ఎంచుకోండి',
    'kn': 'ಒಂದು ಶ್ರೇಣಿಯನ್ನು ಆಯ್ಕೆಮಾಡಿ',
  },
  'Have you supplied similar orders before?': {
    'mr': 'तुम्ही याआधी असेच ऑर्डर पुरवले आहेत का?',
    'bn': 'আপনি আগে এই ধরনের অর্ডার সরবরাহ করেছেন কি?',
    'gu': 'શું તમે પહેલા આવા ઓર્ડર પૂરા પાડ્યા છે?',
    'pa': 'ਕੀ ਤੁਸੀਂ ਪਹਿਲਾਂ ਅਜਿਹੇ ਆਰਡਰ ਸਪਲਾਈ ਕੀਤੇ ਹਨ?',
    'ta': 'இதற்கு முன் இதுபோன்ற ஆர்டர்களை நீங்கள் வழங்கியிருக்கிறீர்களா?',
    'te': 'మీరు ఇంతకు ముందు ఇలాంటి ఆర్డర్‌లను సరఫరా చేశారా?',
    'kn': 'ನೀವು ಈ ಹಿಂದೆ ಇಂತಹ ಆರ್ಡರ್‌ಗಳನ್ನು ಪೂರೈಸಿದ್ದೀರಾ?',
  },
  'This helps explain typical GeM experience criteria. Answering “No” is completely fine.': {
    'mr': 'यामुळे सामान्य GeM अनुभव निकष समजण्यास मदत होते. “नाही” निवडणे पूर्णपणे योग्य आहे.',
    'bn': 'এটি সাধারণ GeM অভিজ্ঞতার শর্ত বুঝতে সাহায্য করে। “না” বেছে নেওয়া সম্পূর্ণ ঠিক আছে।',
    'gu': 'આ સામાન્ય GeM અનુભવ માપદંડ સમજવામાં મદદ કરે છે. “ના” પસંદ કરવું સંપૂર્ણપણે યોગ્ય છે.',
    'pa': 'ਇਹ ਆਮ GeM ਤਜਰਬਾ ਸ਼ਰਤਾਂ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। “ਨਹੀਂ” ਚੁਣਨਾ ਪੂਰੀ ਤਰ੍ਹਾਂ ਠੀਕ ਹੈ।',
    'ta': 'இது வழக்கமான GeM அனுபவ நிபந்தனைகளை விளக்க உதவும். “இல்லை” எனத் தேர்ந்தெடுப்பது முற்றிலும் சரி.',
    'te': 'ఇది సాధారణ GeM అనుభవ ప్రమాణాలను వివరించడంలో సహాయపడుతుంది. “లేదు” ఎంచుకోవడం పూర్తిగా సరైనది.',
    'kn': 'ಇದು ಸಾಮಾನ್ಯ GeM ಅನುಭವ ಮಾನದಂಡಗಳನ್ನು ವಿವರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. “ಇಲ್ಲ” ಎಂದು ಆಯ್ಕೆಮಾಡುವುದು ಸಂಪೂರ್ಣ ಸರಿ.',
  },
  'This helps explain bidding criteria and prepare for relevant bids. It is not a GeM registration form and does not require proof or documents.': {
    'mr': 'हे बोली निकष समजण्यास आणि योग्य बोलींसाठी तयारी करण्यास मदत करते. हे GeM नोंदणी फॉर्म नाही आणि यासाठी पुरावा किंवा कागदपत्रे आवश्यक नाहीत.',
    'bn': 'এটি বিড শর্ত বুঝতে এবং প্রাসঙ্গিক বিডের জন্য প্রস্তুতিতে সাহায্য করে। এটি GeM নিবন্ধন ফর্ম নয় এবং এর জন্য প্রমাণ বা কাগজপত্রের প্রয়োজন নেই।',
    'gu': 'આ બિડ માપદંડ સમજવામાં અને સંબંધિત બિડ માટે તૈયારીમાં મદદ કરે છે. આ GeM નોંધણી ફોર્મ નથી અને તેના માટે પુરાવા અથવા દસ્તાવેજોની જરૂર નથી.',
    'pa': 'ਇਹ ਬੋਲੀ ਸ਼ਰਤਾਂ ਸਮਝਣ ਅਤੇ ਢੁਕਵੀਆਂ ਬੋਲੀਆਂ ਲਈ ਤਿਆਰੀ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ। ਇਹ GeM ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਫਾਰਮ ਨਹੀਂ ਹੈ ਅਤੇ ਇਸ ਲਈ ਸਬੂਤ ਜਾਂ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਲੋੜ ਨਹੀਂ।',
    'ta': 'இது ஏல நிபந்தனைகளை விளக்கவும் தொடர்புடைய ஏலங்களுக்குத் தயாராகவும் உதவுகிறது. இது GeM பதிவு படிவம் அல்ல, ஆதாரம் அல்லது ஆவணங்கள் தேவையில்லை.',
    'te': 'ఇది బిడ్ ప్రమాణాలను వివరించడంలో మరియు సంబంధిత బిడ్‌లకు సిద్ధం కావడంలో సహాయపడుతుంది. ఇది GeM నమోదు ఫారం కాదు మరియు దీనికి రుజువు లేదా పత్రాలు అవసరం లేదు.',
    'kn': 'ಇದು ಬಿಡ್ ಮಾನದಂಡಗಳನ್ನು ವಿವರಿಸಲು ಮತ್ತು ಸಂಬಂಧಿತ ಬಿಡ್‌ಗಳಿಗೆ ತಯಾರಾಗಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಇದು GeM ನೋಂದಣಿ ಫಾರ್ಮ್ ಅಲ್ಲ ಮತ್ತು ಇದಕ್ಕೆ ಪುರಾವೆ ಅಥವಾ ದಾಖಲೆಗಳು ಅಗತ್ಯವಿಲ್ಲ.',
  },
  'Roughly how many, and what total value?': {
    'mr': 'अंदाजे किती, आणि एकूण मूल्य किती?',
    'bn': 'আনুমানিক কতগুলি, এবং মোট মূল্য কত?',
    'gu': 'અંદાજે કેટલા, અને કુલ મૂલ્ય શું?',
    'pa': 'ਲਗਭਗ ਕਿੰਨੇ, ਅਤੇ ਕੁੱਲ ਮੁੱਲ ਕੀ ਹੈ?',
    'ta': 'தோராயமாக எத்தனை, மொத்த மதிப்பு என்ன?',
    'te': 'సుమారుగా ఎన్ని, మరియు మొత్తం విలువ ఎంత?',
    'kn': 'ಸುಮಾರಾಗಿ ಎಷ್ಟು, ಮತ್ತು ಒಟ್ಟು ಮೌಲ್ಯ ಎಷ್ಟು?',
  },
  'Some GeM bids ask about similar past orders. A ballpark helps explain those criteria; both answers are optional.': {
    'mr': 'काही GeM बोली मागील समान ऑर्डरबद्दल विचारतात. अंदाज हे निकष समजण्यास मदत करतो; दोन्ही उत्तरे वैकल्पिक आहेत.',
    'bn': 'কিছু GeM বিড অতীতের একই রকম অর্ডার সম্পর্কে জিজ্ঞাসা করে। একটি আনুমানিক ধারণা এই শর্তগুলি বুঝতে সাহায্য করে; দুটি উত্তরই ঐচ্ছিক।',
    'gu': 'કેટલીક GeM બિડ ભૂતકાળના સમાન ઓર્ડર વિશે પૂછે છે. અંદાજ આ માપદંડ સમજવામાં મદદ કરે છે; બંને જવાબો વૈકલ્પિક છે.',
    'pa': 'ਕੁਝ GeM ਬੋਲੀਆਂ ਪਿਛਲੇ ਸਮਾਨ ਆਰਡਰਾਂ ਬਾਰੇ ਪੁੱਛਦੀਆਂ ਹਨ। ਅਨੁਮਾਨ ਇਹ ਸ਼ਰਤਾਂ ਸਮਝਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ; ਦੋਵੇਂ ਜਵਾਬ ਵਿਕਲਪਿਕ ਹਨ।',
    'ta': 'சில GeM ஏலங்கள் முந்தைய இதுபோன்ற ஆர்டர்களைப் பற்றி கேட்கின்றன. ஒரு தோராயமான மதிப்பீடு இந்த நிபந்தனைகளை விளக்க உதவும்; இரண்டு பதில்களும் விருப்பமானவை.',
    'te': 'కొన్ని GeM బిడ్‌లు గత సారూప్య ఆర్డర్‌ల గురించి అడుగుతాయి. ఒక అంచనా ఈ ప్రమాణాలను వివరించడంలో సహాయపడుతుంది; రెండు సమాధానాలు ఐచ్ఛికం.',
    'kn': 'ಕೆಲವು GeM ಬಿಡ್‌ಗಳು ಹಿಂದಿನ ಇದೇ ರೀತಿಯ ಆರ್ಡರ್‌ಗಳ ಬಗ್ಗೆ ಕೇಳುತ್ತವೆ. ಒಂದು ಅಂದಾಜು ಈ ಮಾನದಂಡಗಳನ್ನು ವಿವರಿಸಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ; ಎರಡೂ ಉತ್ತರಗಳು ಆಯ್ಕಿಕ.',
